screenPanels.initJs:
function(container, apiUrl, tables) {
  // パスワード表示/非表示切り替え
  const togglePasswordBtn = container.querySelector("#toggle-password");
  const passwordInput = container.querySelector("#password");

  togglePasswordBtn.addEventListener("click", () => {
    const isPassword = passwordInput.type === "password";
    passwordInput.type = isPassword ? "text" : "password";
    togglePasswordBtn.textContent = isPassword ? "🙈" : "👁";
  });

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  function hideError() {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.classList.add("hidden");
  }

  // ログインフォーム送信処理
  const loginForm = container.querySelector("#login-form");
  loginForm.addEventListener("submit", async (e) => {
    e.preventDefault();
    hideError();

    const userId = container.querySelector("#user-id").value.trim();
    const password = container.querySelector("#password").value;
    const rememberMe = container.querySelector("#remember-me").checked;

    if (!userId || !password) {
      showError("ユーザーIDとパスワードを入力してください");
      return;
    }

    // ログインボタンを無効化
    const loginBtn = container.querySelector("#login-btn");
    const originalText = loginBtn.textContent;
    loginBtn.textContent = "ログイン中...";
    loginBtn.disabled = true;

    try {
      // ユーザーテーブル（tables[0]）からユーザー情報を取得
      const users = await window.aivicApi.list(0);

      if (!users) {
        showError("システムエラーが発生しました");
        return;
      }

      // ユーザー認証（実際の実装ではハッシュ化されたパスワードと比較）
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        showError("ユーザーIDまたはパスワードが正しくありません");
        return;
      }

      // 簡易パスワード検証（実際の実装では適切なハッシュ検証を行う）
      // ここではデモ用に固定パスワード "password" または ユーザー名と同じ場合を許可
      if (password !== "password" && password !== userId) {
        showError("ユーザーIDまたはパスワードが正しくありません");
        return;
      }

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態を保存（localStorage）
      if (rememberMe) {
        localStorage.setItem("worklog_user_id", userId);
        localStorage.setItem("worklog_login_time", new Date().toISOString());
      } else {
        sessionStorage.setItem("worklog_user_id", userId);
        sessionStorage.setItem("worklog_login_time", new Date().toISOString());
      }

      // ユーザー情報をセッションに保存
      sessionStorage.setItem("worklog_user_info", JSON.stringify({
        ユーザーID: user.ユーザーID,
        ユーザー名: user.ユーザー名,
        氏名: user.氏名,
        所属部署: user.所属部署,
        職種: user.職種,
        権限レベル: user.権限レベル
      }));

      // ログイン成功 - メイン画面（工数記録画面）に遷移
      window.onLoginSuccess();

    } catch (error) {
      console.error("Login error:", error);
      showError("ログイン処理中にエラーが発生しました");
    } finally {
      // ログインボタンを復元
      loginBtn.textContent = originalText;
      loginBtn.disabled = false;
    }
  });

  // パスワードを忘れた場合のリンク
  container.querySelector("#forgot-password").addEventListener("click", (e) => {
    e.preventDefault();
    alert("パスワードリセットについては、システム管理者にお問い合わせください。");
  });

  // 保存されたログイン情報があれば自動入力
  const savedUserId = localStorage.getItem("worklog_user_id") || sessionStorage.getItem("worklog_user_id");
  if (savedUserId) {
    container.querySelector("#user-id").value = savedUserId;
    container.querySelector("#remember-me").checked = !!localStorage.getItem("worklog_user_id");
  }

  // フォーカスを最初の入力フィールドに設定
  setTimeout(() => {
    const userIdInput = container.querySelector("#user-id");
    if (!userIdInput.value) {
      userIdInput.focus();
    } else {
      container.querySelector("#password").focus();
    }
  }, 100);
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let timerInterval = null;

  // 作業履歴テーブル再描画
  function renderWorkHistory(records) {
    const tbody = container.querySelector("#work-history-tbody");
    const today = new Date().toISOString().split('T')[0];
    const todayRecords = records.filter(r => r.作業日 && r.作業日.startsWith(today));

    tbody.innerHTML = todayRecords.map(record => {
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${String(record.作業時間 % 60).padStart(2, '0')}` : '';
      const status = record.進捗状況 || '';
      const statusColor = status === '作業中' ? 'color: var(--primary)' : status === '完了' ? 'color: #22c55e' : 'color: var(--text)';

      return `<tr data-id="${record.id}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">${startTime}</td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">${endTime}</td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">${record.作業種別 || ''}</td>
        <td style="padding: 6px 8px; font-size: 12px; color: var(--text);">${workTime}</td>
        <td style="padding: 6px 8px; font-size: 12px; font-weight: 500; ${statusColor}">${status}</td>
      </tr>`;
    }).join("");
  }

  // 作業項目選択肢を設定
  function loadWorkItems() {
    const select = container.querySelector("#work-item-select");
    const workItems = tables[3]?.records || []; // 作業項目マスタ

    select.innerHTML = '<option value="">作業項目を選択してください</option>' +
      workItems.filter(item => item.有効フラグ).map(item => 
        `<option value="${item.id}">${item.作業項目名}</option>`
      ).join("");
  }

  // 現在時刻更新
  function updateCurrentTime() {
    const timeElement = container.querySelector("#current-time");
    const now = new Date();
    timeElement.textContent = now.toLocaleString('ja-JP', {
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
  }

  // 経過時間更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    const elapsed = Math.floor((now - startTime) / 1000);
    const hours = Math.floor(elapsed / 3600);
    const minutes = Math.floor((elapsed % 3600) / 60);
    const seconds = elapsed % 60;

    const elapsedElement = container.querySelector("#elapsed-time");
    elapsedElement.textContent = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  // 作業開始
  async function startWork() {
    const workItemSelect = container.querySelector("#work-item-select");
    if (!workItemSelect.value) {
      alert("作業項目を選択してください");
      return;
    }

    const workItem = tables[3].records.find(item => item.id === workItemSelect.value);
    if (!workItem) return;

    const workRecord = {
      作業員ID: "current-user-id", // 実際の実装では認証済みユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: "現場作業",
      作業場所: "現場",
      作業種別: workItem.作業項目名,
      作業内容: workItem.作業項目説明 || "",
      進捗状況: "作業中",
      承認状態: "未承認",
      作成者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(1, workRecord); // 作業記録テーブル
    if (saved) {
      currentWorkRecord = saved;
      startTime = new Date();

      // UI更新
      container.querySelector("#btn-start-work").disabled = true;
      container.querySelector("#btn-end-work").disabled = false;
      container.querySelector("#btn-pause-work").disabled = false;

      // タイマー開始
      timerInterval = setInterval(updateElapsedTime, 1000);

      // 履歴更新
      const records = await window.aivicApi.list(1);
      if (records) renderWorkHistory(records);
    }
  }

  // 作業終了
  async function endWork() {
    if (!currentWorkRecord) return;

    const endTime = new Date();
    const workTimeMinutes = Math.floor((endTime - startTime) / 60000);
    const memo = container.querySelector("#work-memo").value;

    const updated = await window.aivicApi.update(1, currentWorkRecord.id, {
      作業終了時刻: endTime.toISOString(),
      作業時間: workTimeMinutes,
      進捗状況: "完了",
      作業内容: memo || currentWorkRecord.作業内容
    });

    if (updated) {
      // UI リセット
      currentWorkRecord = null;
      startTime = null;
      clearInterval(timerInterval);

      container.querySelector("#btn-start-work").disabled = false;
      container.querySelector("#btn-end-work").disabled = true;
      container.querySelector("#btn-pause-work").disabled = true;
      container.querySelector("#elapsed-time").textContent = "00:00:00";
      container.querySelector("#work-memo").value = "";
      container.querySelector("#work-item-select").value = "";

      // 履歴更新
      const records = await window.aivicApi.list(1);
      if (records) renderWorkHistory(records);
    }
  }

  // 作業中断
  async function pauseWork() {
    const pauseReasonArea = container.querySelector("#pause-reason-area");
    pauseReasonArea.classList.remove("hidden");

    const reasonSelect = container.querySelector("#pause-reason-select");
    const reasonDetail = container.querySelector("#pause-reason-detail");

    if (!reasonSelect.value) {
      alert("中断理由を選択してください");
      return;
    }

    if (currentWorkRecord) {
      // 中断記録を作成
      const pauseRecord = {
        作業記録ID: currentWorkRecord.id,
        中断開始日時: new Date().toISOString(),
        中断理由区分: reasonSelect.value,
        中断理由詳細: reasonDetail.value,
        対応状況: "対応中",
        記録者ID: "current-user-id"
      };

      await window.aivicApi.save(2, pauseRecord); // 中断記録テーブル

      // 作業記録の状態を中断に更新
      await window.aivicApi.update(1, currentWorkRecord.id, {
        進捗状況: "中断"
      });

      // タイマー停止
      clearInterval(timerInterval);

      // UI更新
      container.querySelector("#btn-start-work").disabled = false;
      container.querySelector("#btn-end-work").disabled = true;
      container.querySelector("#btn-pause-work").disabled = true;

      // 履歴更新
      const records = await window.aivicApi.list(1);
      if (records) renderWorkHistory(records);

      // 中断理由エリアを非表示
      pauseReasonArea.classList.add("hidden");
      reasonSelect.value = "";
      reasonDetail.value = "";
    }
  }

  // 初期データ読み込み
  renderWorkHistory(tables[1]?.records || []);
  loadWorkItems();

  // 現在時刻の定期更新
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);

  // イベントリスナー
  container.querySelector("#btn-start-work").addEventListener("click", startWork);
  container.querySelector("#btn-end-work").addEventListener("click", endWork);
  container.querySelector("#btn-pause-work").addEventListener("click", pauseWork);

  container.querySelector("#btn-save").addEventListener("click", async () => {
    const memo = container.querySelector("#work-memo").value;
    if (currentWorkRecord && memo) {
      await window.aivicApi.update(1, currentWorkRecord.id, {
        作業内容: memo
      });
      alert("メモを保存しました");
    }
  });

  container.querySelector("#btn-cancel").addEventListener("click", () => {
    container.querySelector("#work-memo").value = "";
    container.querySelector("#pause-reason-area").classList.add("hidden");
  });

  // 画面遷移
  container.querySelector("#btn-work-start-nav").addEventListener("click", () => {
    window.showScreen("scr-1778907187615");
  });

  container.querySelector("#btn-work-history").addEventListener("click", () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector("#btn-emergency-report").addEventListener("click", () => {
    window.showScreen("scr-1778907330826");
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");

  // 1. テーブル再描画関数を定義
  async function renderRows(rows) {
    // 中断回数を計算するため中断記録テーブルも取得
    const interruptionRecords = await window.aivicApi.list(2) || [];

    tbody.innerHTML = rows.map(r => {
      const workDate = r.作業日 ? new Date(r.作業日).toLocaleDateString('ja-JP') : '';
      const startTime = r.作業開始時刻 ? new Date(r.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = r.作業終了時刻 ? new Date(r.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workTime = r.作業時間 ? `${Math.floor(r.作業時間 / 60)}時間${r.作業時間 % 60}分` : '';

      // この作業記録の中断回数を計算
      const interruptionCount = interruptionRecords.filter(ir => ir.作業記録ID === r.作業記録ID).length;

      return `
        <tr data-id="${r.作業記録ID}" style="height: 36px;">
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${workDate}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${r.プロジェクト名 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${r.作業種別 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${startTime}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${endTime}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">${workTime}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px; text-align: center;">${interruptionCount}</td>
          <td style="padding: 6px 10px; color: var(--text); font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${r.進捗状況 === '完了' ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : r.進捗状況 === '作業中' ? 'background: rgba(59, 130, 246, 0.2); color: #3b82f6;' : 'background: rgba(239, 68, 68, 0.2); color: #ef4444;'}">${r.進捗状況 || ''}</span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID}" style="font-size: 11px; padding: 4px 8px;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データを即座に描画
  renderRows(tables[1].records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const status = container.querySelector("#filter-status").value;

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const filteredRows = rows.filter(r => {
      let match = true;

      if (startDate && r.作業日) {
        const workDate = new Date(r.作業日).toISOString().split('T')[0];
        if (workDate < startDate) match = false;
      }

      if (endDate && r.作業日) {
        const workDate = new Date(r.作業日).toISOString().split('T')[0];
        if (workDate > endDate) match = false;
      }

      if (status && r.進捗状況 !== status) match = false;

      return match;
    });

    renderRows(filteredRows);
  });

  // 4. リセットボタンのイベントリスナー
  container.querySelector("#btn-reset").addEventListener("click", async () => {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-status").value = '';

    const rows = await window.aivicApi.list(1);
    if (rows) renderRows(rows);
  });

  // 5. CSVエクスポートボタンのイベントリスナー
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const interruptionRecords = await window.aivicApi.list(2) || [];

    const headers = ['作業日', 'プロジェクト名', '作業種別', '開始時刻', '終了時刻', '作業時間', '中断回数', '進捗状況', '作業場所', '作業内容'];
    const csvData = rows.map(r => {
      const workDate = r.作業日 ? new Date(r.作業日).toLocaleDateString('ja-JP') : '';
      const startTime = r.作業開始時刻 ? new Date(r.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const endTime = r.作業終了時刻 ? new Date(r.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
      const workTime = r.作業時間 ? `${Math.floor(r.作業時間 / 60)}時間${r.作業時間 % 60}分` : '';
      const interruptionCount = interruptionRecords.filter(ir => ir.作業記録ID === r.作業記録ID).length;

      return [
        workDate,
        r.プロジェクト名 || '',
        r.作業種別 || '',
        startTime,
        endTime,
        workTime,
        interruptionCount,
        r.進捗状況 || '',
        r.作業場所 || '',
        r.作業内容 || ''
      ].map(field => `"${String(field).replace(/"/g, '""')}"`);
    });

    const csvContent = '\uFEFF' + [headers.map(h => `"${h}"`), ...csvData].map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '作業履歴一覧.csv';
    link.click();
  });

  // 6. データ抽出ボタンのイベントリスナー
  container.querySelector("#btn-data-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  // 7. 戻るボタンのイベントリスナー
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 8. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#anomaly-log-tbody');
  const detailArea = container.querySelector('#detail-area');
  const noSelection = container.querySelector('#no-selection');
  let selectedLogId = null;
  let currentUser = { id: 'user-001', name: '管理者' }; // 仮の現在ユーザー

  // 重要度に応じたバッジスタイル
  function getSeverityBadge(severity) {
    const styles = {
      '高': 'background: #ff4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '中': 'background: #ff8800; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '低': 'background: #4488ff; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[severity] || styles['低']}">${severity}</span>`;
  }

  // 確認状況に応じたバッジスタイル
  function getStatusBadge(status) {
    const styles = {
      '未確認': 'background: #666; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '確認済み': 'background: #ff8800; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '対応済み': 'background: #22cc22; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return `<span style="${styles[status] || styles['未確認']}">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="cursor: pointer;" class="log-row">
        <td style="padding: 6px 10px;">${new Date(r.検出日時).toLocaleString('ja-JP')}</td>
        <td style="padding: 6px 10px;">${r.作業員名 || ''}</td>
        <td style="padding: 6px 10px;">${r.異常値種別 || ''}</td>
        <td style="padding: 6px 10px;">${r.検出項目 || ''}</td>
        <td style="padding: 6px 10px;">${r.検出値 || ''}</td>
        <td style="padding: 6px 10px;">${r.閾値 || ''}</td>
        <td style="padding: 6px 10px;">${getSeverityBadge(r.重要度)}</td>
        <td style="padding: 6px 10px;">${getStatusBadge(r.確認状況)}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary view-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ描画
  renderRows(tables[4].records || []);

  // フィルター適用
  function applyFilters() {
    window.aivicApi.list(4).then(rows => {
      if (!rows) return;

      const dateStart = container.querySelector('#filter-date-start').value;
      const dateEnd = container.querySelector('#filter-date-end').value;
      const anomalyType = container.querySelector('#filter-anomaly-type').value;
      const workerName = container.querySelector('#filter-worker-name').value;
      const severity = container.querySelector('#filter-severity').value;
      const status = container.querySelector('#filter-status').value;

      let filtered = rows.filter(r => {
        if (dateStart && new Date(r.検出日時) < new Date(dateStart)) return false;
        if (dateEnd && new Date(r.検出日時) > new Date(dateEnd)) return false;
        if (anomalyType && r.異常値種別 !== anomalyType) return false;
        if (workerName && !r.作業員名?.includes(workerName)) return false;
        if (severity && r.重要度 !== severity) return false;
        if (status && r.確認状況 !== status) return false;
        return true;
      });

      renderRows(filtered);
    });
  }

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#filter-date-start').value = '';
    container.querySelector('#filter-date-end').value = '';
    container.querySelector('#filter-anomaly-type').value = '';
    container.querySelector('#filter-worker-name').value = '';
    container.querySelector('#filter-severity').value = '';
    container.querySelector('#filter-status').value = '';
    window.aivicApi.list(4).then(renderRows);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', () => {
    window.aivicApi.list(4).then(rows => {
      if (!rows) return;

      const headers = ['検出日時', '作業員名', '異常値種別', '検出項目', '検出値', '閾値', '重要度', '確認状況', '対応メモ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          `"${new Date(r.検出日時).toLocaleString('ja-JP')}"`,
          `"${r.作業員名 || ''}"`,
          `"${r.異常値種別 || ''}"`,
          `"${r.検出項目 || ''}"`,
          `"${r.検出値 || ''}"`,
          `"${r.閾値 || ''}"`,
          `"${r.重要度 || ''}"`,
          `"${r.確認状況 || ''}"`,
          `"${r.対応メモ || ''}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `異常値検出ログ_${new Date().toISOString().slice(0,10)}.csv`;
      link.click();
    });
  });

  // 行クリック・詳細表示
  container.addEventListener('click', async (e) => {
    const row = e.target.closest('.log-row');
    const viewBtn = e.target.closest('.view-btn');

    if (row || viewBtn) {
      const id = (row || viewBtn).dataset.id;
      selectedLogId = id;

      const rows = await window.aivicApi.list(4);
      const log = rows?.find(r => r.id === id);

      if (log) {
        detailArea.style.display = 'block';
        noSelection.style.display = 'none';

        container.querySelector('#update-status').value = log.確認状況 || '未確認';
        container.querySelector('#update-reviewer').value = log.確認者名 || currentUser.name;
        container.querySelector('#update-memo').value = log.対応メモ || '';

        // 選択行をハイライト
        container.querySelectorAll('.log-row').forEach(r => r.style.background = '');
        if (row) row.style.background = 'rgba(255,255,255,0.05)';
      }
    }
  });

  // 更新ボタン
  container.querySelector('#btn-update').addEventListener('click', async () => {
    if (!selectedLogId) return;

    const status = container.querySelector('#update-status').value;
    const memo = container.querySelector('#update-memo').value;

    const updateData = {
      確認状況: status,
      確認者ID: currentUser.id,
      確認者名: currentUser.name,
      確認日時: new Date().toISOString(),
      対応メモ: memo
    };

    const updated = await window.aivicApi.update(4, selectedLogId, updateData);
    if (updated) {
      alert('更新しました');
      applyFilters();
    }
  });

  // 作業記録確認ボタン
  container.querySelector('#btn-view-record').addEventListener('click', () => {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });
}

function(container, apiUrl, tables) {
  // 現在日時を更新する関数
  function updateDateTime() {
    const now = new Date();
    const formatted = `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
    container.querySelector("#current-datetime").textContent = formatted;
  }

  // 作業項目マスタを読み込んでセレクトボックスに設定
  function loadWorkItems() {
    window.aivicApi.list(3).then(items => {
      if (!items) return;
      const select = container.querySelector("#work-item");
      select.innerHTML = '<option value="">選択してください</option>';
      items.filter(item => item.有効フラグ).forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    });
  }

  // 進行中作業を描画
  function renderActiveWorks(works) {
    const tbody = container.querySelector("#active-works-tbody");
    tbody.innerHTML = works.map(work => `
      <tr data-id="${work.作業記録ID}">
        <td style="padding: 6px 8px; font-size: 12px;">${work.作業種別 || ''}</td>
        <td style="padding: 6px 8px; font-size: 12px;">${work.作業開始時刻 ? new Date(work.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</td>
        <td style="padding: 6px 8px;">
          <button class="action-btn secondary pause-btn" data-id="${work.作業記録ID}" style="padding: 2px 6px; font-size: 11px;">中断</button>
          <button class="action-btn end-btn" data-id="${work.作業記録ID}" style="padding: 2px 6px; font-size: 11px; background: var(--primary); color: #fff;">終了</button>
        </td>
      </tr>
    `).join('');
  }

  // 中断中作業を描画
  function renderPausedWorks(works) {
    const tbody = container.querySelector("#paused-works-tbody");
    tbody.innerHTML = works.map(work => `
      <tr data-id="${work.作業記録ID}">
        <td style="padding: 6px 8px; font-size: 12px;">${work.作業種別 || ''}</td>
        <td style="padding: 6px 8px; font-size: 12px;">${work.中断開始日時 ? new Date(work.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</td>
        <td style="padding: 6px 8px;">
          <button class="action-btn resume-btn" data-id="${work.作業記録ID}" style="padding: 2px 6px; font-size: 11px; background: var(--primary); color: #fff;">再開</button>
        </td>
      </tr>
    `).join('');
  }

  // 作業状況を読み込み
  function loadWorkStatus() {
    // 進行中作業（作業中ステータス）
    window.aivicApi.list(1).then(works => {
      if (works) {
        const activeWorks = works.filter(work => work.進捗状況 === '作業中');
        renderActiveWorks(activeWorks);
      }
    });

    // 中断中作業（中断記録から取得）
    window.aivicApi.list(2).then(interruptions => {
      if (interruptions) {
        const pausedWorks = interruptions.filter(int => int.対応状況 === '対応中');
        renderPausedWorks(pausedWorks);
      }
    });
  }

  // 初期化
  updateDateTime();
  setInterval(updateDateTime, 60000); // 1分ごとに更新
  loadWorkItems();
  loadWorkStatus();

  // 作業開始ボタン
  container.querySelector("#btn-start-work").addEventListener("click", async () => {
    const workItemId = container.querySelector("#work-item").value;
    const location = container.querySelector("#work-location").value;
    const memo = container.querySelector("#work-memo").value;

    if (!workItemId) {
      alert("作業項目を選択してください");
      return;
    }
    if (!location) {
      alert("作業場所を入力してください");
      return;
    }

    // 選択された作業項目の詳細を取得
    const workItems = await window.aivicApi.list(3);
    const selectedItem = workItems?.find(item => item.作業項目ID === workItemId);

    const workRecord = {
      作業員ID: "current-user-id", // 実際の実装では現在ログイン中のユーザーIDを使用
      作業日: new Date().toISOString(),
      作業開始時刻: new Date().toISOString(),
      プロジェクト名: "現場作業",
      作業場所: location,
      作業種別: selectedItem?.作業項目名|| "",
      作業内容: selectedItem?.作業項目名|| "",
      進捗状況: "作業中",
      備考: memo,
      承認状態: "未承認",
      作成者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      // フォームクリア
      container.querySelector("#work-item").value = "";
      container.querySelector("#work-location").value = "";
      container.querySelector("#work-memo").value = "";

      // 作業状況を再読み込み
      loadWorkStatus();
      alert("作業を開始しました");
    }
  });

  // 作業操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 中断ボタン
    const pauseBtn = e.target.closest(".pause-btn");
    if (pauseBtn) {
      const workId = pauseBtn.dataset.id;
      const reason = prompt("中断理由を入力してください");
      if (!reason) return;

      const interruption = {
        作業記録ID: workId,
        中断開始日時: new Date().toISOString(),
        中断理由区分: "その他",
        中断理由詳細: reason,
        対応状況: "対応中",
        記録者ID: "current-user-id"
      };

      const saved = await window.aivicApi.save(2, interruption);
      if (saved) {
        // 作業記録の進捗状況を中断に更新
        await window.aivicApi.update(1, workId, { 進捗状況: "中断" });
        loadWorkStatus();
        alert("作業を中断しました");
      }
    }

    // 終了ボタン
    const endBtn = e.target.closest(".end-btn");
    if (endBtn) {
      if (!confirm("作業を終了しますか？")) return;

      const workId = endBtn.dataset.id;
      const endTime = new Date().toISOString();

      // 作業時間を計算（簡易実装）
      const work = await window.aivicApi.list(1).then(works => works?.find(w => w.作業記録ID === workId));
      let workMinutes = 0;
      if (work?.作業開始時刻) {
        const startTime = new Date(work.作業開始時刻);
        const endTimeObj = new Date(endTime);
        workMinutes = Math.floor((endTimeObj - startTime) / (1000 * 60));
      }

      const updated = await window.aivicApi.update(1, workId, {
        作業終了時刻: endTime,
        作業時間: workMinutes,
        進捗状況: "完了"
      });

      if (updated) {
        loadWorkStatus();
        alert("作業を終了しました");
      }
    }

    // 再開ボタン
    const resumeBtn = e.target.closest(".resume-btn");
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;

      // 中断記録を終了
      const interruptions = await window.aivicApi.list(2);
      const activeInterruption = interruptions?.find(int => int.作業記録ID === workId && int.対応状況 === "対応中");

      if (activeInterruption) {
        await window.aivicApi.update(2, activeInterruption.中断記録ID, {
          中断終了日時: new Date().toISOString(),
          対応状況: "解決済み"
        });
      }

      // 作業記録を作業中に戻す
      const updated = await window.aivicApi.update(1, workId, { 進捗状況: "作業中" });

      if (updated) {
        loadWorkStatus();
        alert("作業を再開しました");
      }
    }
  });

  // 工数入力画面への遷移
  container.querySelector("#btn-work-input").addEventListener("click", () => {
    window.showScreen("scr-1778907296658");
  });

  // 設定ボタン（プレースホルダー）
  container.querySelector("#btn-settings").addEventListener("click", () => {
    alert("設定画面は未実装です");
  });

  // ログアウトボタン
  container.querySelector("#btn-logout").addEventListener("click", () => {
    if (confirm("ログアウトしますか？")) {
      // 実際の実装では認証情報をクリアする処理を行う
      alert("ログアウトしました");
    }
  });
}

function(container, apiUrl, tables) {
  // 現在進行中の作業記録を取得（実際の実装では作業中のレコードを特定）
  let currentWorkRecord = null;

  // 初期データの読み込みと表示
  async function loadCurrentWork() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (workRecords) {
        // 進行中の作業を検索（実際には現在ログイン中のユーザーの作業中レコード）
        currentWorkRecord = workRecords.find(r => r.進捗状況 === '作業中') || workRecords[0];

        if (currentWorkRecord) {
          // 作業情報を表示
          container.querySelector('#work-item-name').textContent = currentWorkRecord.作業内容 || '作業項目';
          container.querySelector('#work-location').textContent = currentWorkRecord.作業場所 || '';

          // 時刻の表示
          if (currentWorkRecord.作業開始時刻) {
            const startTime = new Date(currentWorkRecord.作業開始時刻);
            container.querySelector('#start-time').textContent = startTime.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
          }

          // 終了時刻を現在時刻に設定
          const now = new Date();
          container.querySelector('#end-time').textContent = now.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});

          // 時間計算
          if (currentWorkRecord.作業開始時刻) {
            const startTime = new Date(currentWorkRecord.作業開始時刻);
            const totalMinutes = Math.floor((now - startTime) / (1000 * 60));
            const hours = Math.floor(totalMinutes / 60);
            const minutes = totalMinutes % 60;

            container.querySelector('#total-time').textContent = `${hours}時間${minutes}分`;

            // 中断時間を取得
            const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
            let totalBreakMinutes = 0;
            if (breakRecords) {
              const workBreaks = breakRecords.filter(b => b.作業記録ID === currentWorkRecord.作業記録ID);
              totalBreakMinutes = workBreaks.reduce((sum, b) => sum + (b.中断時間 || 0), 0);
            }

            const breakHours = Math.floor(totalBreakMinutes / 60);
            const breakMins = totalBreakMinutes % 60;
            container.querySelector('#break-time').textContent = `${breakHours}時間${breakMins}分`;

            const actualMinutes = totalMinutes - totalBreakMinutes;
            const actualHours = Math.floor(actualMinutes / 60);
            const actualMins = actualMinutes % 60;
            container.querySelector('#actual-time').textContent = `${actualHours}時間${actualMins}分`;
          }
        }
      }
    } catch (error) {
      console.error('作業記録の読み込みに失敗しました:', error);
    }
  }

  // 異常報告チェックボックスの制御
  const hasIssueCheckbox = container.querySelector('#has-issue');
  const issueSection = container.querySelector('#issue-section');

  hasIssueCheckbox.addEventListener('change', function() {
    if (this.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      container.querySelector('#issue-detail').value = '';
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!currentWorkRecord) {
      alert('作業記録が見つかりません');
      return;
    }

    const completionStatus = container.querySelector('#completion-status').value;
    const workMemo = container.querySelector('#work-memo').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueDetail = container.querySelector('#issue-detail').value;

    try {
      // 作業記録を更新
      const now = new Date();
      const startTime = new Date(currentWorkRecord.作業開始時刻);
      const totalMinutes = Math.floor((now - startTime) / (1000 * 60));

      const updateData = {
        作業終了時刻: now.toISOString(),
        作業時間: totalMinutes,
        進捗状況: completionStatus === 'completed' ? '完了' : 
                 completionStatus === 'partial' ? '部分完了' :
                 completionStatus === 'suspended' ? '中断' : '延期',
        備考: workMemo,
        更新日時: now.toISOString()
      };

      const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue && issueDetail.trim()) {
          const logData = {
            異常値検出ログID: crypto.randomUUID(),
            検出対象テーブル: '作業記録',
            検出対象レコードID: currentWorkRecord.作業記録ID,
            ユーザーID: currentWorkRecord.作業員ID,
            異常値種別: '作業員報告',
            検出項目: '作業内容',
            検出値: issueDetail,
            閾値: '手動報告',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: now.toISOString(),
            作成日時: now.toISOString(),
            更新日時: now.toISOString()
          };

          await window.aivicApi.save(4, logData); // 異常値検出ログテーブル
        }

        alert('工数記録を確定しました');
        window.showScreen("scr-1778907226171"); // 記録確認画面へ遷移
      } else {
        alert('記録の更新に失敗しました');
      }
    } catch (error) {
      console.error('記録確定エラー:', error);
      alert('記録の確定中にエラーが発生しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('作業を終了せずに戻りますか？')) {
      window.showScreen("scr-1778907226171"); // 記録確認画面へ遷移
    }
  });

  // ボタンホバー効果
  const confirmBtn = container.querySelector('#btn-confirm');
  confirmBtn.addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });
  confirmBtn.addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  const cancelBtn = container.querySelector('#btn-cancel');
  cancelBtn.addEventListener('mouseenter', function() {
    this.style.background = 'rgba(255,255,255,0.05)';
  });
  cancelBtn.addEventListener('mouseleave', function() {
    this.style.background = 'transparent';
  });

  // 初期データ読み込み
  loadCurrentWork();
}

function(container, apiUrl, tables) {
  // 自動保存の状態管理
  let autoSaveInterval = null;
  let localData = JSON.parse(localStorage.getItem('workRecordLocalData') || '[]');

  // ローカルデータテーブル再描画
  function renderLocalData(data) {
    const tbody = container.querySelector('#local-data-tbody');
    tbody.innerHTML = data.map(item => `
      <tr data-id="${item.id}">
        <td>${item.id.substring(0, 8)}...</td>
        <td>${item.workerName || '未設定'}</td>
        <td>${item.workContent || '作業内容未入力'}</td>
        <td>${new Date(item.savedAt).toLocaleString()}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 11px; ${item.synced ? 'background: rgba(34,197,94,0.2); color: #22c55e;' : 'background: rgba(239,68,68,0.2); color: #ef4444;'}">
            ${item.synced ? '同期済み' : '同期待ち'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary sync-btn" data-id="${item.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">同期</button>
          <button class="action-btn secondary delete-local-btn" data-id="${item.id}" style="background: transparent; color: #ef4444; border: 1px solid rgba(239,68,68,0.3); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ネットワーク状態チェック
  function updateNetworkStatus() {
    const statusEl = container.querySelector('#network-status');
    if (navigator.onLine) {
      statusEl.textContent = 'オンライン';
      statusEl.style.color = '#22c55e';
    } else {
      statusEl.textContent = 'オフライン';
      statusEl.style.color = '#ef4444';
    }
  }

  // 同期待ちデータ件数更新
  function updatePendingCount() {
    const pendingCount = localData.filter(item => !item.synced).length;
    container.querySelector('#pending-sync-count').textContent = `${pendingCount}件`;
  }

  // エラー表示
  function showError(message) {
    const errorEl = container.querySelector('#error-notification');
    const messageEl = container.querySelector('#error-message');
    messageEl.textContent = message;
    errorEl.style.display = 'block';
  }

  // 自動保存処理
  function startAutoSave() {
    const interval = parseInt(container.querySelector('#save-interval').value) * 1000;

    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(async () => {
      // 未保存の作業記録データがあるかチェック（実際の実装では現在の入力状態をチェック）
      const unsavedData = {
        id: 'temp_' + Date.now(),
        workerName: '現在のユーザー',
        workContent: '自動保存データ',
        savedAt: new Date().toISOString(),
        synced: false
      };

      // ローカルストレージに保存
      localData.push(unsavedData);
      localStorage.setItem('workRecordLocalData', JSON.stringify(localData));

      // 最終保存時刻更新
      container.querySelector('#last-save-time').textContent = new Date().toLocaleString();

      // 表示更新
      renderLocalData(localData);
      updatePendingCount();

      // オンラインの場合は同期を試行
      if (navigator.onLine) {
        await syncPendingData();
      }
    }, interval);

    container.querySelector('#auto-save-status').textContent = '有効';
    container.querySelector('#auto-save-status').style.color = 'var(--primary)';
  }

  // 同期処理
  async function syncPendingData() {
    const pendingItems = localData.filter(item => !item.synced);

    for (const item of pendingItems) {
      try {
        // 作業記録テーブルに保存（tableIndex = 1）
        const saved = await window.aivicApi.save(1, {
          作業員ID: 'user_001',
          作業日: new Date().toISOString(),
          作業開始時刻: new Date().toISOString(),
          作業時間: 60,
          プロジェクト名: 'プロジェクトA',
          作業場所: '現場A',
          作業種別: '設置',
          作業内容: item.workContent,
          進捗状況: '作業中',
          承認状態: '未承認',
          作成者ID: 'user_001'
        });

        if (saved) {
          // 同期成功
          item.synced = true;
        }
      } catch (error) {
        showError(`データ同期エラー: ${error.message}`);
        break;
      }
    }

    localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
    renderLocalData(localData);
    updatePendingCount();
  }

  // 初期化
  renderLocalData(localData);
  updateNetworkStatus();
  updatePendingCount();
  startAutoSave();

  // ネットワーク状態監視
  window.addEventListener('online', updateNetworkStatus);
  window.addEventListener('offline', updateNetworkStatus);

  // 手動同期ボタン
  container.querySelector('#btn-manual-sync').addEventListener('click', async () => {
    await syncPendingData();
  });

  // 保存間隔変更
  container.querySelector('#save-interval').addEventListener('change', () => {
    startAutoSave();
  });

  // エラー通知閉じる
  container.querySelector('#btn-dismiss-error').addEventListener('click', () => {
    container.querySelector('#error-notification').style.display = 'none';
  });

  // 検索機能
  container.querySelector('#btn-search-local').addEventListener('click', () => {
    const keyword = container.querySelector('#search-local-data').value.toLowerCase();
    const filtered = localData.filter(item => 
      JSON.stringify(item).toLowerCase().includes(keyword)
    );
    renderLocalData(filtered);
  });

  // ローカルデータ操作
  container.addEventListener('click', async (e) => {
    const syncBtn = e.target.closest('.sync-btn');
    const deleteBtn = e.target.closest('.delete-local-btn');

    if (syncBtn) {
      const id = syncBtn.dataset.id;
      const item = localData.find(item => item.id === id);
      if (item && !item.synced) {
        try {
          const saved = await window.aivicApi.save(1, {
            作業員ID: 'user_001',
            作業日: new Date().toISOString(),
            作業開始時刻: new Date().toISOString(),
            作業時間: 60,
            プロジェクト名: 'プロジェクトA',
            作業場所: '現場A',
            作業種別: '設置',
            作業内容: item.workContent,
            進捗状況: '作業中',
            承認状態: '未承認',
            作成者ID: 'user_001'
          });

          if (saved) {
            item.synced = true;
            localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
            renderLocalData(localData);
            updatePendingCount();
          }
        } catch (error) {
          showError(`同期エラー: ${error.message}`);
        }
      }
    }

    if (deleteBtn) {
      if (!confirm('このローカルデータを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      localData = localData.filter(item => item.id !== id);
      localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
      renderLocalData(localData);
      updatePendingCount();
    }
  });

  // バックアップ機能
  container.querySelector('#btn-backup-local').addEventListener('click', () => {
    const dataStr = JSON.stringify(localData, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `work_record_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // 復元機能
  container.querySelector('#btn-restore-backup').addEventListener('click', () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
      const file = e.target.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          try {
            const restoredData = JSON.parse(e.target.result);
            localData = restoredData;
            localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
            renderLocalData(localData);
            updatePendingCount();
            alert('バックアップから復元しました');
          } catch (error) {
            showError('バックアップファイルの形式が正しくありません');
          }
        };
        reader.readAsText(file);
      }
    };
    input.click();
  });

  // ローカルデータクリア
  container.querySelector('#btn-clear-local').addEventListener('click', () => {
    if (!confirm('すべてのローカルデータを削除しますか？この操作は取り消せません。')) return;

    localData = [];
    localStorage.setItem('workRecordLocalData', JSON.stringify(localData));
    renderLocalData(localData);
    updatePendingCount();
  });

  // 設定変更ボタン（設定画面への遷移）
  container.querySelector('#btn-settings').addEventListener('click', () => {
    // 設定画面が存在する場合の遷移（現在は該当画面がないためアラート）
    alert('保存設定の詳細変更機能は今後実装予定です');
  });
}

function(container, apiUrl, tables) {
  // 現在のユーザーIDを取得（仮想的に設定）
  const currentUserId = localStorage.getItem('currentUserId') || 'user-001';

  // 中断時間を計算する関数
  function calculateBreakTime(workRecordId, breakRecords) {
    if (!breakRecords || breakRecords.length === 0) return 0;

    const recordBreaks = breakRecords.filter(b => b.作業記録ID === workRecordId);
    return recordBreaks.reduce((total, b) => total + (b.中断時間 || 0), 0);
  }

  // 異常値チェック関数
  function hasAnomalies(record, anomalyLogs) {
    if (!anomalyLogs || anomalyLogs.length === 0) return false;
    return anomalyLogs.some(log => 
      log.検出対象レコードID === record.作業記録ID && 
      log.確認状況 === '未確認'
    );
  }

  // 時間フォーマット関数
  function formatTime(dateTimeStr) {
    if (!dateTimeStr) return '-';
    const date = new Date(dateTimeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  // 日付フォーマット関数
  function formatDate(dateTimeStr) {
    if (!dateTimeStr) return '-';
    const date = new Date(dateTimeStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 分を時間:分形式に変換
  function formatDuration(minutes) {
    if (!minutes || minutes === 0) return '-';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return hours > 0 ? `${hours}:${mins.toString().padStart(2, '0')}` : `${mins}分`;
  }

  // 承認状態のバッジスタイル
  function getApprovalBadgeStyle(status) {
    switch(status) {
      case '承認済み':
        return 'background: #10b981; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      case '差し戻し':
        return 'background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
      default:
        return 'background: #f59e0b; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;';
    }
  }

  // テーブル再描画関数
  function renderRows(workRecords) {
    const tbody = container.querySelector('#records-tbody');
    const breakRecords = tables[2]?.records || [];
    const anomalyLogs = tables[4]?.records || [];

    // 現在のユーザーの記録のみフィルタ
    const userRecords = workRecords.filter(r => r.作業員ID === currentUserId);

    tbody.innerHTML = userRecords.map(record => {
      const breakTime = calculateBreakTime(record.作業記録ID, breakRecords);
      const hasAnomaly = hasAnomalies(record, anomalyLogs);
      const anomalyIcon = hasAnomaly ? '<span style="color: #ef4444; margin-left: 4px;" title="異常値検出">⚠️</span>' : '';

      return `
        <tr data-id="${record.作業記録ID}" style="height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px;">${formatDate(record.作業日)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.プロジェクト名 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${record.作業種別 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatTime(record.作業開始時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatTime(record.作業終了時刻)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDuration(record.作業時間)}${anomalyIcon}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${formatDuration(breakTime)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="${getApprovalBadgeStyle(record.承認状態)}">${record.承認状態 || '未承認'}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary edit-btn" data-id="${record.作業記録ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">修正</button>
            <button class="action-btn secondary delete-btn" data-id="${record.作業記録ID}" style="background: transparent; color: #ef4444; border: 1px solid #ef4444; padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ描画
  renderRows(tables[1]?.records || []);

  // 絞り込みボタン
  container.querySelector('#btn-filter').addEventListener('click', async () => {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;

    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const filtered = allRecords.filter(record => {
      // 日付フィルタ
      if (startDate && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate < startDate) return false;
      }
      if (endDate && record.作業日) {
        const recordDate = new Date(record.作業日).toISOString().split('T')[0];
        if (recordDate > endDate) return false;
      }

      // 承認状態フィルタ
      if (approvalStatus && record.承認状態 !== approvalStatus) return false;

      return true;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const allRecords = await window.aivicApi.list(1);
    if (!allRecords) return;

    const userRecords = allRecords.filter(r => r.作業員ID === currentUserId);
    const breakRecords = await window.aivicApi.list(2) || [];

    const csvData = [
      ['作業日', 'プロジェクト名', '作業種別', '開始時刻', '終了時刻', '作業時間(分)', '中断時間(分)', '承認状態', '作業内容']
    ];

    userRecords.forEach(record => {
      const breakTime = calculateBreakTime(record.作業記録ID, breakRecords);
      csvData.push([
        formatDate(record.作業日),
        record.プロジェクト名 || '',
        record.作業種別 || '',
        formatTime(record.作業開始時刻),
        formatTime(record.作業終了時刻),
        record.作業時間 || 0,
        breakTime,
        record.承認状態 || '未承認',
        record.作業内容 || ''
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業記録_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // メニューに戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen('scr-1778907133295');
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この作業記録を削除しますか？')) return;

      const recordId = deleteBtn.dataset.id;
      const success = await window.aivicApi.delete(1, recordId);
      if (success) {
        const updatedRecords = await window.aivicApi.list(1);
        if (updatedRecords) renderRows(updatedRecords);
      }
      return;
    }

    // 修正ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const recordId = editBtn.dataset.id;
      // 修正画面に遷移（記録IDをlocalStorageに保存）
      localStorage.setItem('editRecordId', recordId);
      window.showScreen('scr-1778907343735');
      return;
    }
  });

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#filter-start-date').value = today;
  container.querySelector('#filter-end-date').value = today;
}

function(container, apiUrl, tables) {
  let startTime = null;
  let timerInterval = null;
  let isRecording = false;
  let mediaRecorder = null;
  let audioChunks = [];

  // 現在時刻を中断開始時刻に設定
  const now = new Date();
  const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
  container.querySelector("#input-start-time").value = localDateTime;
  startTime = now;

  // 経過時間の更新
  function updateElapsedTime() {
    if (startTime) {
      const elapsed = Math.floor((Date.now() - startTime.getTime()) / 1000);
      const minutes = Math.floor(elapsed / 60);
      const seconds = elapsed % 60;
      container.querySelector("#elapsed-time").textContent = 
        `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    }
  }

  // タイマー開始
  timerInterval = setInterval(updateElapsedTime, 1000);
  updateElapsedTime();

  // 関連作業項目の表示（現在進行中の作業記録から取得）
  async function loadCurrentWorkItem() {
    const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
    if (workRecords) {
      const currentWork = workRecords.find(r => r.進捗状況 === '作業中');
      if (currentWork) {
        container.querySelector("#work-item-display").textContent = 
          `${currentWork.プロジェクト名} - ${currentWork.作業種別}`;
      }
    }
  }
  loadCurrentWorkItem();

  // 写真選択
  container.querySelector("#btn-photo").addEventListener("click", () => {
    container.querySelector("#input-photo").click();
  });

  container.querySelector("#input-photo").addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (file) {
      container.querySelector("#photo-preview").textContent = `選択済み: ${file.name}`;
    }
  });

  // 音声録音
  container.querySelector("#btn-voice").addEventListener("click", async () => {
    const btn = container.querySelector("#btn-voice");
    const status = container.querySelector("#voice-status");

    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
          status.textContent = `録音完了 (${Math.round(audioBlob.size / 1024)}KB)`;
        };

        mediaRecorder.start();
        isRecording = true;
        btn.textContent = "🔴 録音停止";
        status.textContent = "録音中...";
      } catch (error) {
        status.textContent = "マイクへのアクセスが拒否されました";
      }
    } else {
      mediaRecorder.stop();
      mediaRecorder.stream.getTracks().forEach(track => track.stop());
      isRecording = false;
      btn.textContent = "🎤 録音開始";
    }
  });

  // 一時保存
  container.querySelector("#btn-temp-save").addEventListener("click", async () => {
    const formData = collectFormData();
    formData.対応状況 = "対応中";

    const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
    if (saved) {
      alert("一時保存しました");
    }
  });

  // 中断記録完了
  container.querySelector("#btn-complete").addEventListener("click", async () => {
    const formData = collectFormData();

    if (!formData.中断理由区分) {
      alert("中断理由を選択してください");
      return;
    }

    formData.対応状況 = "記録完了";

    const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル
    if (saved) {
      if (timerInterval) {
        clearInterval(timerInterval);
      }
      window.showScreen("scr-1778907251446"); // 作業再開記録画面
    }
  });

  // フォームデータ収集
  function collectFormData() {
    const startTimeValue = container.querySelector("#input-start-time").value;
    const reason = container.querySelector("#select-reason").value;
    const details = container.querySelector("#textarea-details").value;
    const location = container.querySelector("#input-location").value;

    // 緊急度取得
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const urgency = urgencyRadio ? urgencyRadio.value : "中";

    // 影響範囲取得
    const impactCheckboxes = container.querySelectorAll('input[type="checkbox"]:checked');
    const impacts = Array.from(impactCheckboxes).map(cb => cb.value);

    // 中断時間計算（分単位）
    const elapsedMinutes = startTime ? Math.floor((Date.now() - startTime.getTime()) / 60000) : 0;

    return {
      作業記録ID: "current-work-id", // 実際は現在の作業記録IDを設定
      中断開始日時: startTimeValue ? new Date(startTimeValue).toISOString() : new Date().toISOString(),
      中断理由区分: reason,
      中断理由詳細: details,
      中断時間: elapsedMinutes,
      影響度: urgency,
      記録者ID: "current-user-id", // 実際は現在のユーザーIDを設定
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };
  }

  // 中断開始時刻変更時にタイマーリセット
  container.querySelector("#input-start-time").addEventListener("change", (e) => {
    if (e.target.value) {
      startTime = new Date(e.target.value);
      updateElapsedTime();
    }
  });

  // クリーンアップ
  window.addEventListener('beforeunload', () => {
    if (timerInterval) {
      clearInterval(timerInterval);
    }
    if (isRecording && mediaRecorder) {
      mediaRecorder.stop();
      mediaRecorder.stream.getTracks().forEach(track => track.stop());
    }
  });
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedSuspendRecord = null;

  // 現在時刻を設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    container.querySelector("#resume-time").value = localDateTime;
  }

  // 中断時間を計算（分単位）
  function calculateSuspendDuration(suspendStart) {
    const now = new Date();
    const start = new Date(suspendStart);
    return Math.floor((now - start) / (1000 * 60));
  }

  // 中断中作業一覧の再描画
  function renderSuspendedWorks(workRecords, suspendRecords) {
    const tbody = container.querySelector("#suspended-work-tbody");

    // 中断中の作業記録を抽出（進捗状況が「中断」）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === "中断");

    tbody.innerHTML = suspendedWorks.map(work => {
      // 対応する中断記録を検索（中断終了日時がnull）
      const suspendRecord = suspendRecords.find(s => 
        s.作業記録ID === work.作業記録ID && !s.中断終了日時
      );

      const suspendStart = suspendRecord ? suspendRecord.中断開始日時 : "";
      const suspendReason = suspendRecord ? suspendRecord.中断理由区分 : "";
      const suspendDuration = suspendRecord ? calculateSuspendDuration(suspendStart) : 0;

      return `
        <tr data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">
          <td>${work.作業内容 || ""}</td>
          <td>${work.プロジェクト名 || ""}</td>
          <td>${suspendStart ? new Date(suspendStart).toLocaleString() : ""}</td>
          <td>${suspendReason}</td>
          <td>${suspendDuration}分</td>
          <td>
            <button class="action-btn resume-btn" data-work-id="${work.作業記録ID}" data-suspend-id="${suspendRecord?.中断記録ID || ''}">
              再開
            </button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const workRecords = await window.aivicApi.list(1); // 作業記録
      const suspendRecords = await window.aivicApi.list(2); // 中断記録

      if (workRecords && suspendRecords) {
        renderSuspendedWorks(workRecords, suspendRecords);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 作業再開処理
  async function resumeWork() {
    if (!selectedWorkRecord || !selectedSuspendRecord) {
      alert("作業が選択されていません");
      return;
    }

    const resumeTime = container.querySelector("#resume-time").value;
    const reasonCategory = container.querySelector("#resume-reason-category").value;
    const reasonDetail = container.querySelector("#resume-reason-detail").value;

    if (!resumeTime || !reasonCategory) {
      alert("再開時刻と再開理由区分は必須です");
      return;
    }

    if (!confirm("作業を再開しますか？")) {
      return;
    }

    try {
      // 中断記録を更新（中断終了日時を設定）
      const updatedSuspend = await window.aivicApi.update(2, selectedSuspendRecord.中断記録ID, {
        中断終了日時: resumeTime,
        中断時間: calculateSuspendDuration(selectedSuspendRecord.中断開始日時),
        対応状況: "解決済み"
      });

      // 作業記録を更新（進捗状況を「作業中」に変更）
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: "作業中"
      });

      if (updatedSuspend && updatedWork) {
        alert("作業を再開しました");
        // 工数入力画面に遷移
        window.showScreen("scr-1778907296658");
      } else {
        alert("作業再開の記録に失敗しました");
      }
    } catch (error) {
      console.error("作業再開エラー:", error);
      alert("作業再開の記録に失敗しました");
    }
  }

  // イベントリスナー設定
  container.addEventListener("click", async (e) => {
    // 再開ボタンクリック
    const resumeBtn = e.target.closest(".resume-btn");
    if (resumeBtn) {
      const workId = resumeBtn.dataset.workId;
      const suspendId = resumeBtn.dataset.suspendId;

      try {
        const workRecords = await window.aivicApi.list(1);
        const suspendRecords = await window.aivicApi.list(2);

        selectedWorkRecord = workRecords.find(w => w.作業記録ID === workId);
        selectedSuspendRecord = suspendRecords.find(s => s.中断記録ID === suspendId);

        if (selectedWorkRecord && selectedSuspendRecord) {
          // 選択された作業情報を表示
          container.querySelector("#selected-work-name").textContent = selectedWorkRecord.作業内容;
          container.querySelector("#selected-project-name").textContent = selectedWorkRecord.プロジェクト名;
          container.querySelector("#selected-suspend-time").textContent = new Date(selectedSuspendRecord.中断開始日時).toLocaleString();
          container.querySelector("#selected-suspend-reason").textContent = selectedSuspendRecord.中断理由区分;

          // 現在時刻を設定
          setCurrentTime();

          // フォームを表示
          container.querySelector("#resume-form").classList.remove("hidden");
        }
      } catch (error) {
        console.error("作業選択エラー:", error);
      }
    }

    // 作業再開ボタン
    if (e.target.id === "btn-resume") {
      await resumeWork();
    }

    // キャンセルボタン
    if (e.target.id === "btn-cancel") {
      container.querySelector("#resume-form").classList.add("hidden");
      selectedWorkRecord = null;
      selectedSuspendRecord = null;
    }

    // 戻るボタン
    if (e.target.id === "btn-back") {
      window.history.back();
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  // チェック結果の更新
  function updateCheckResults() {
    // 異常値検出ログから最新のチェック結果を取得
    window.aivicApi.list(4).then(logs => {
      if (!logs) return;

      const recentLogs = logs.filter(log => {
        const logDate = new Date(log.検出日時);
        const now = new Date();
        return (now - logDate) < 24 * 60 * 60 * 1000; // 24時間以内
      });

      // ステータスアイコンとテキストの更新
      const statusIcon = container.querySelector('#status-icon');
      const statusText = container.querySelector('#status-text');
      const saveStatusText = container.querySelector('#save-status-text');

      const highPriorityLogs = recentLogs.filter(log => log.重要度 === '高');
      const mediumPriorityLogs = recentLogs.filter(log => log.重要度 === '中');

      if (highPriorityLogs.length > 0) {
        statusIcon.style.background = '#ef4444';
        statusText.textContent = 'エラーあり';
        saveStatusText.textContent = '不可';
        saveStatusText.style.color = '#ef4444';
      } else if (mediumPriorityLogs.length > 0) {
        statusIcon.style.background = '#f59e0b';
        statusText.textContent = '警告あり';
        saveStatusText.textContent = '要確認';
        saveStatusText.style.color = '#f59e0b';
      } else {
        statusIcon.style.background = '#22c55e';
        statusText.textContent = 'チェック完了';
        saveStatusText.textContent = '可能';
        saveStatusText.style.color = '#22c55e';
      }

      // 異常値件数の更新
      const anomalyNotification = container.querySelector('#anomaly-notification');
      if (recentLogs.length > 0) {
        anomalyNotification.innerHTML = `
          <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <span style="color: #ef4444;">!</span>
            <span style="color: var(--text);">${recentLogs.length}件の異常値</span>
          </div>
          <button id="btn-anomaly-detail" class="action-btn secondary" style="font-size: 11px; padding: 3px 8px; margin-top: 4px;">
            詳細確認
          </button>
        `;
      } else {
        anomalyNotification.innerHTML = `
          <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <span style="color: #22c55e;">✓</span>
            <span style="color: var(--text);">異常値なし</span>
          </div>
        `;
      }
    });
  }

  // 作業記録の入力チェック
  function checkWorkRecords() {
    window.aivicApi.list(1).then(records => {
      if (!records) return;

      const requiredCheckList = container.querySelector('#required-check-list');
      const formatErrorList = container.querySelector('#format-error-list');
      const datetimeCheckResult = container.querySelector('#datetime-check-result');
      const worktimeWarning = container.querySelector('#worktime-warning');

      // 最新の作業記録をチェック
      const latestRecord = records[records.length - 1];
      if (!latestRecord) return;

      // 必須項目チェック
      const requiredFields = [
        { field: '作業員ID', value: latestRecord.作業員ID },
        { field: '作業日', value: latestRecord.作業日 },
        { field: '作業開始時刻', value: latestRecord.作業開始時刻 },
        { field: 'プロジェクト名', value: latestRecord.プロジェクト名 },
        { field: '作業内容', value: latestRecord.作業内容 }
      ];

      requiredCheckList.innerHTML = requiredFields.map(field => {
        const isValid = field.value && field.value.toString().trim() !== '';
        return `
          <div class="check-item" style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <span style="color: ${isValid ? '#22c55e' : '#ef4444'};">${isValid ? '✓' : '✗'}</span>
            <span style="color: var(--text);">${field.field}</span>
          </div>
        `;
      }).join('');

      // 日時整合性チェック
      if (latestRecord.作業開始時刻 && latestRecord.作業終了時刻) {
        const startTime = new Date(latestRecord.作業開始時刻);
        const endTime = new Date(latestRecord.作業終了時刻);

        if (startTime >= endTime) {
          datetimeCheckResult.innerHTML = `
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
              <span style="color: #ef4444;">✗</span>
              <span style="color: var(--text);">開始時刻 ≥ 終了時刻</span>
            </div>
            <div style="color: var(--text-muted); font-size: 11px;">
              ${startTime.toLocaleString()} ≥ ${endTime.toLocaleString()}
            </div>
          `;
        } else {
          datetimeCheckResult.innerHTML = `
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
              <span style="color: #22c55e;">✓</span>
              <span style="color: var(--text);">日時整合性OK</span>
            </div>
          `;
        }
      }

      // 作業時間妥当性チェック
      if (latestRecord.作業時間) {
        const workMinutes = parseInt(latestRecord.作業時間);
        const workHours = Math.floor(workMinutes / 60);
        const workMins = workMinutes % 60;

        if (workMinutes > 480) { // 8時間超過
          worktimeWarning.innerHTML = `
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
              <span style="color: #f59e0b;">⚠</span>
              <span style="color: var(--text);">長時間作業検出</span>
            </div>
            <div style="color: var(--text-muted); font-size: 11px;">
              連続${workHours}時間${workMins}分（標準8時間を超過）
            </div>
          `;
        } else {
          worktimeWarning.innerHTML = `
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
              <span style="color: #22c55e;">✓</span>
              <span style="color: var(--text);">作業時間適正</span>
            </div>
          `;
        }
      }
    });
  }

  // 重複データチェック
  function checkDuplicateData() {
    window.aivicApi.list(1).then(records => {
      if (!records) return;

      const duplicateAlert = container.querySelector('#duplicate-alert');

      // 同じ作業員・同じ日・同じ時間帯の記録をチェック
      const duplicates = [];
      for (let i = 0; i < records.length; i++) {
        for (let j = i + 1; j < records.length; j++) {
          const r1 = records[i];
          const r2 = records[j];

          if (r1.作業員ID === r2.作業員ID && 
              r1.作業日 === r2.作業日 &&
              r1.作業開始時刻=== r2.作業開始時刻) {
            duplicates.push({ r1, r2 });
          }
        }
      }

      if (duplicates.length > 0) {
        duplicateAlert.innerHTML = `
          <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <span style="color: #ef4444;">!</span>
            <span style="color: var(--text);">${duplicates.length}件の重複</span>
          </div>
        `;
      } else {
        duplicateAlert.innerHTML = `
          <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 4px;">
            <span style="color: #22c55e;">✓</span>
            <span style="color: var(--text);">重複なし</span>
          </div>
        `;
      }
    });
  }

  // 初期チェック実行
  updateCheckResults();
  checkWorkRecords();
  checkDuplicateData();

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    updateCheckResults();
    checkWorkRecords();
    checkDuplicateData();
  });

  // ログ出力ボタン
  container.querySelector('#btn-export-log').addEventListener('click', () => {
    window.aivicApi.list(4).then(logs => {
      if (!logs) return;

      const csvContent = '\uFEFF' + [
        '検出日時,異常値種別,検出項目,検出値,閾値,重要度,確認状況',
        ...logs.map(log => [
          log.検出日時 || '',
          log.異常値種別 || '',
          log.検出項目 || '',
          log.検出値 || '',
          log.閾値 || '',
          log.重要度 || '',
          log.確認状況 || ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `入力チェックログ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  });

  // 異常値詳細確認ボタン
  container.addEventListener('click', (e) => {
    if (e.target.id === 'btn-anomaly-detail') {
      window.showScreen('scr-1778907170814'); // 異常値検出ログ画面
    }
  });

  // 修正入力画面へボタン
  container.querySelector('#btn-fix-input').addEventListener('click', () => {
    window.showScreen('scr-1778907319067'); // 修正入力画面
  });

  // 強制保存ボタン
  container.querySelector('#btn-force-save').addEventListener('click', () => {
    if (confirm('エラーがある状態で保存しますか？')) {
      // 最新の作業記録を強制保存
      window.aivicApi.list(1).then(records => {
        if (records && records.length > 0) {
          const latestRecord = records[records.length - 1];
          window.aivicApi.update(1, latestRecord.作業記録ID, {
            ...latestRecord,
            承認状態: '強制保存'
          }).then(() => {
            alert('強制保存が完了しました');
          });
        }
      });
    }
  });

  // 再チェック実行ボタン
  container.querySelector('#btn-recheck').addEventListener('click', () => {
    updateCheckResults();
    checkWorkRecords();
    checkDuplicateData();

    // 新しい異常値検出を実行
    window.aivicApi.list(1).then(records => {
      if (!records) return;

      records.forEach(record => {
        // 長時間作業の検出
        if (record.作業時間 && parseInt(record.作業時間) > 480) {
          window.aivicApi.save(4, {
            検出対象テーブル: '作業記録',
            検出対象レコードID: record.作業記録ID,
            ユーザーID: record.作業員ID,
            異常値種別: '長時間作業',
            検出項目: '作業時間',
            検出値: `${record.作業時間}分`,
            閾値: '480分',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString()
          });
        }
      });

      setTimeout(() => {
        updateCheckResults();
        alert('再チェックが完了しました');
      }, 500);
    });
  });
}

