function(container, apiUrl, tables) {
  let currentValidationResults = [];
  let selectedRecordId = null;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  const startDate = container.querySelector('#input-start-date');
  const endDate = container.querySelector('#input-end-date');
  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
  startDate.value = oneWeekAgo.toISOString().split('T')[0];
  endDate.value = today;

  // 検証結果テーブル再描画
  function renderValidationResults(results) {
    const tbody = container.querySelector('#validation-results');
    const resultCount = container.querySelector('#result-count');

    currentValidationResults = results;
    resultCount.textContent = `${results.length}件`;

    if (results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; padding: 20px; color: var(--text-muted);">検証結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(r => {
      const severityColor = r.重要度 === '高' ? '#ef4444' : r.重要度 === '中' ? '#f59e0b' : '#10b981';
      const statusColor = r.確認状況 === '未確認' ? '#ef4444' : r.確認状況 === '確認済み' ? '#f59e0b' : '#10b981';

      return `
        <tr data-id="${r.id || r.異常値検出ログID}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="row-checkbox" data-id="${r.id || r.異常値検出ログID}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${new Date(r.検出日時 || r.作成日時).toLocaleString()}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.作業員名 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.異常値種別 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出項目 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出値 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.閾値 || 'N/A'}</td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${severityColor}20; color: ${severityColor};">${r.重要度 || 'N/A'}</span>
          </td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${statusColor}20; color: ${statusColor};">${r.確認状況 || 'N/A'}</span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary correct-btn" data-id="${r.id || r.異常値検出ログID}" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">修正</button>
            <button class="action-btn secondary approve-btn" data-id="${r.id || r.異常値検出ログID}" style="padding: 4px 8px; font-size: 11px;">承認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ表示（異常値検出ログテーブルから）
  const anomalyTableIndex = tables.findIndex(t => t.tableName.includes('異常値検出ログ'));
  if (anomalyTableIndex >= 0) {
    renderValidationResults(tables[anomalyTableIndex].records || []);
  }

  // 検証実行
  container.querySelector('#btn-validate').addEventListener('click', async () => {
    const startDateVal = startDate.value;
    const endDateVal = endDate.value;
    const target = container.querySelector('#select-target').value;

    if (!startDateVal || !endDateVal) {
      alert('検証期間を選択してください');
      return;
    }

    const progressArea = container.querySelector('#progress-area');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressPercent = container.querySelector('#progress-percent');
    const notificationArea = container.querySelector('#notification-area');

    progressArea.style.display = 'block';
    notificationArea.style.display = 'none';

    // 検証進捗シミュレーション
    const steps = ['データ取得中...', '整合性チェック中...', '異常値検出中...', '結果集計中...'];
    for (let i = 0; i < steps.length; i++) {
      progressText.textContent = steps[i];
      const percent = ((i + 1) / steps.length) * 100;
      progressBar.style.width = `${percent}%`;
      progressPercent.textContent = `${Math.round(percent)}%`;
      await new Promise(resolve => setTimeout(resolve, 800));
    }

    // 異常値検出ログを取得して表示
    try {
      const anomalyLogs = await window.aivicApi.list(anomalyTableIndex);
      if (anomalyLogs) {
        // 期間でフィルタリング
        const filtered = anomalyLogs.filter(log => {
          const logDate = new Date(log.検出日時 || log.作成日時).toISOString().split('T')[0];
          return logDate >= startDateVal && logDate <= endDateVal;
        });

        renderValidationResults(filtered);

        // 完了通知
        progressArea.style.display = 'none';
        notificationArea.style.display = 'block';
        container.querySelector('#notification-text').textContent = `検証完了: ${filtered.length}件の異常値を検出しました`;
      }
    } catch (error) {
      progressArea.style.display = 'none';
      alert('検証処理でエラーが発生しました');
    }
  });

  // フィルタリング
  container.querySelector('#btn-filter').addEventListener('click', () => {
    const errorType = container.querySelector('#filter-error-type').value;
    const severity = container.querySelector('#filter-severity').value;
    const status = container.querySelector('#filter-status').value;

    let filtered = [...currentValidationResults];

    if (errorType) {
      filtered = filtered.filter(r => r.異常値種別 === errorType);
    }
    if (severity) {
      filtered = filtered.filter(r => r.重要度 === severity);
    }
    if (status) {
      filtered = filtered.filter(r => r.確認状況 === status);
    }

    renderValidationResults(filtered);
  });

  // 全選択チェックボックス
  container.querySelector('#check-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括承認
  container.querySelector('#btn-bulk-approve').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('承認する項目を選択してください');
      return;
    }

    if (!confirm(`${checkedBoxes.length}件の異常値を承認しますか？`)) return;

    for (const checkbox of checkedBoxes) {
      const id = checkbox.dataset.id;
      await window.aivicApi.update(anomalyTableIndex, id, { 確認状況: '対応済み', 確認日時: new Date().toISOString() });
    }

    // 再読み込み
    const refreshedData = await window.aivicApi.list(anomalyTableIndex);
    if (refreshedData) {
      renderValidationResults(refreshedData);
    }

    alert('一括承認が完了しました');
  });

  // 個別操作（修正・承認）
  container.addEventListener('click', async (e) => {
    const correctBtn = e.target.closest('.correct-btn');
    const approveBtn = e.target.closest('.approve-btn');

    if (correctBtn) {
      selectedRecordId = correctBtn.dataset.id;
      showCorrectionModal(selectedRecordId);
    }

    if (approveBtn) {
      const id = approveBtn.dataset.id;
      if (!confirm('この異常値を承認しますか？')) return;

      await window.aivicApi.update(anomalyTableIndex, id, { 
        確認状況: '対応済み', 
        確認日時: new Date().toISOString() 
      });

      const refreshedData = await window.aivicApi.list(anomalyTableIndex);
      if (refreshedData) {
        renderValidationResults(refreshedData);
      }
    }
  });

  // 修正モーダル表示
  function showCorrectionModal(recordId) {
    const modal = container.querySelector('#correction-modal');
    const form = container.querySelector('#correction-form');

    // 対象レコードを取得
    const record = currentValidationResults.find(r => (r.id || r.異常値検出ログID) === recordId);
    if (!record) return;

    form.innerHTML = `
      <div style="margin-bottom: 12px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">対応メモ</label>
        <textarea id="correction-memo" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; line-height: 1.4; width: 100%; height: 80px; resize: vertical;" placeholder="修正内容や対応状況を入力してください"></textarea>
      </div>
      <div style="margin-bottom: 12px;">
        <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">確認状況</label>
        <select id="correction-status" style="padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px; line-height: 1.4; width: 100%;">
          <option value="確認済み">確認済み</option>
          <option value="対応済み">対応済み</option>
        </select>
      </div>
    `;

    modal.style.display = 'block';
  }

  // モーダル操作
  container.querySelector('#btn-cancel-correction').addEventListener('click', () => {
    container.querySelector('#correction-modal').style.display = 'none';
  });

  container.querySelector('#btn-save-correction').addEventListener('click', async () => {
    const memo = container.querySelector('#correction-memo').value;
    const status = container.querySelector('#correction-status').value;

    if (!selectedRecordId) return;

    await window.aivicApi.update(anomalyTableIndex, selectedRecordId, {
      対応メモ: memo,
      確認状況: status,
      確認日時: new Date().toISOString()
    });

    container.querySelector('#correction-modal').style.display = 'none';

    const refreshedData = await window.aivicApi.list(anomalyTableIndex);
    if (refreshedData) {
      renderValidationResults(refreshedData);
    }

    alert('修正内容を保存しました');
  });

  // 再検証
  container.querySelector('#btn-re-validate').addEventListener('click', () => {
    container.querySelector('#btn-validate').click();
  });

  // ログ出力
  container.querySelector('#btn-export-log').addEventListener('click', async () => {
    try {
      const logs = await window.aivicApi.list(anomalyTableIndex);
      if (!logs) return;

      const csvHeader = '検出日時,作業員,エラー種別,検出項目,検出値,閾値,重要度,確認状況,対応メモ\n';
      const csvRows = logs.map(log => [
        new Date(log.検出日時 || log.作成日時).toLocaleString(),
        log.作業員名 || '',
        log.異常値種別 || '',
        log.検出項目 || '',
        log.検出値 || '',
        log.閾値 || '',
        log.重要度 || '',
        log.確認状況 || '',
        (log.対応メモ || '').replace(/"/g, '""')
      ].map(field => `"${field}"`).join(',')).join('\n');

      const csvContent = '\uFEFF' + csvHeader + csvRows;
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('ログ出力でエラーが発生しました');
    }
  });

  // 異常値ログ一覧画面への遷移
  container.querySelector('#btn-back-to-list').addEventListener('click', () => {
    window.showScreen('scr-1778907170814');
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecordId = null;
  let savedInterruptions = [];

  // 作業項目マスタの読み込み
  async function loadWorkItems() {
    const workItems = await window.aivicApi.list(3); // 作業項目マスタ
    const select = container.querySelector("#select-work-item");
    if (workItems) {
      workItems.forEach(item => {
        const option = document.createElement("option");
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
    }
  }

  // 実働時間の計算
  function calculateWorkHours() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);

      if (end > start) {
        const diffMs = end - start;
        const diffMinutes = Math.floor(diffMs / (1000 * 60)) - breakTime;

        if (diffMinutes > 0) {
          const hours = Math.floor(diffMinutes / 60);
          const minutes = diffMinutes % 60;
          container.querySelector("#display-work-hours").textContent = 
            `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
        } else {
          container.querySelector("#display-work-hours").textContent = "00:00";
        }
      } else {
        container.querySelector("#display-work-hours").textContent = "--:--";
      }
    } else {
      container.querySelector("#display-work-hours").textContent = "--:--";
    }
  }

  // 中断記録の表示更新
  function renderInterruptions() {
    const container_interruptions = container.querySelector("#saved-interruptions");
    if (savedInterruptions.length === 0) {
      container_interruptions.innerHTML = '<p style="font-size: 11px; color: var(--text-muted); margin: 0;">中断記録はありません</p>';
    } else {
      container_interruptions.innerHTML = savedInterruptions.map((interruption, index) => `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; margin-bottom: 4px; background: rgba(255,255,255,0.02);">
          <div style="font-size: 12px; color: var(--text);">
            <strong>${interruption.中断理由区分}</strong> - ${interruption.中断時間}分
            ${interruption.中断理由詳細 ? `<span style="color: var(--text-muted);"> (${interruption.中断理由詳細})</span>` : ''}
          </div>
          <button class="delete-interruption-btn" data-index="${index}" style="background: transparent; color: var(--text-muted); border: none; padding: 2px 6px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </div>
      `).join("");
    }
  }

  // 初期設定
  loadWorkItems();

  // 現在日時を初期値に設定
  const today = new Date();
  container.querySelector("#input-work-date").value = today.toISOString().split('T')[0];

  // 時間入力の変更監視
  container.querySelector("#input-start-time").addEventListener("change", calculateWorkHours);
  container.querySelector("#input-end-time").addEventListener("change", calculateWorkHours);
  container.querySelector("#input-break-time").addEventListener("input", calculateWorkHours);

  // 中断追加ボタン
  container.querySelector("#btn-add-interruption").addEventListener("click", () => {
    const interruptionList = container.querySelector("#interruption-list");
    interruptionList.style.display = interruptionList.style.display === "none" ? "block" : "none";
  });

  // 中断保存ボタン
  container.querySelector("#btn-save-interruption").addEventListener("click", () => {
    const reason = container.querySelector("#select-interruption-reason").value;
    const time = parseInt(container.querySelector("#input-interruption-time").value);
    const detail = container.querySelector("#input-interruption-detail").value;

    if (!reason || !time) {
      alert("中断理由と時間を入力してください");
      return;
    }

    savedInterruptions.push({
      中断理由区分: reason,
      中断時間: time,
      中断理由詳細: detail,
      中断開始日時: new Date().toISOString(),
      対応状況: "記録済み"
    });

    // フォームクリア
    container.querySelector("#select-interruption-reason").value = "";
    container.querySelector("#input-interruption-time").value = "";
    container.querySelector("#input-interruption-detail").value = "";
    container.querySelector("#interruption-list").style.display = "none";

    renderInterruptions();
  });

  // 中断削除
  container.addEventListener("click", (e) => {
    const deleteBtn = e.target.closest(".delete-interruption-btn");
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      savedInterruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // 作業記録保存ボタン
  container.querySelector("#btn-save-work").addEventListener("click", async () => {
    const workDate = container.querySelector("#input-work-date").value;
    const workItemId = container.querySelector("#select-work-item").value;
    const workLocation = container.querySelector("#input-work-location").value;
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const workType = container.querySelector("#select-work-type").value;
    const projectName = container.querySelector("#input-project-name").value;
    const workDetail = container.querySelector("#textarea-work-detail").value;

    if (!workDate || !workItemId || !workLocation || !startTime || !workType || !projectName || !workDetail) {
      alert("必須項目を全て入力してください");
      return;
    }

    // 作業時間の計算
    let workTimeMinutes = null;
    if (endTime) {
      const start = new Date(`${workDate}T${startTime}`);
      const end = new Date(`${workDate}T${endTime}`);
      const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;
      workTimeMinutes = Math.floor((end - start) / (1000 * 60)) - breakTime;
    }

    const workRecord = {
      作業員ID: "current-user-id", // 実際の実装では認証済みユーザーIDを使用
      作業日: new Date(`${workDate}T${startTime}`).toISOString(),
      作業開始時刻: new Date(`${workDate}T${startTime}`).toISOString(),
      作業終了時刻: endTime ? new Date(`${workDate}T${endTime}`).toISOString() : null,
      作業時間: workTimeMinutes,
      プロジェクト名: projectName,
      作業場所: workLocation,
      作業種別: workType,
      作業内容: workDetail,
      進捗状況: endTime ? "完了" : "作業中",
      承認状態: "未承認",
      作成者ID: "current-user-id"
    };

    const saved = await window.aivicApi.save(1, workRecord); // 作業記録テーブル
    if (saved) {
      currentWorkRecordId = saved.作業記録ID;

      // 中断記録も保存
      for (const interruption of savedInterruptions) {
        await window.aivicApi.save(2, {
          ...interruption,
          作業記録ID: currentWorkRecordId,
          記録者ID: "current-user-id"
        });
      }

      alert("作業記録を保存しました");
    }
  });

  // 作業中断ボタン
  container.querySelector("#btn-interruption").addEventListener("click", () => {
    window.showScreen("scr-1778907238439");
  });

  // 作業終了ボタン
  container.querySelector("#btn-end-work").addEventListener("click", () => {
    window.showScreen("scr-1778907199709");
  });

  // 初期表示
  renderInterruptions();
}

function(container, apiUrl, tables) {
  let currentAnomalies = [];
  let selectedAnomalyId = null;

  // 異常値検出ログテーブルのインデックスを取得
  const anomalyTableIndex = tables.findIndex(t => t.tableName === '異常値検出ログ');
  const userTableIndex = tables.findIndex(t => t.tableName === 'ユーザー');

  // 重要度に応じたバッジスタイル
  function getSeverityBadge(severity) {
    const styles = {
      '高': 'background: #ff4757; color: #fff;',
      '中': 'background: #ffa502; color: #fff;',
      '低': 'background: #57606f; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${styles[severity] || styles['低']}">${severity}</span>`;
  }

  // 確認状況に応じたバッジスタイル
  function getStatusBadge(status) {
    const styles = {
      '未確認': 'background: #ff6a00; color: #fff;',
      '確認済み': 'background: #3742fa; color: #fff;',
      '対応済み': 'background: #2ed573; color: #fff;'
    };
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${styles[status] || styles['未確認']}">${status}</span>`;
  }

  // 異常値一覧を再描画
  function renderAnomalies(anomalies) {
    const tbody = container.querySelector('#anomaly-tbody');
    const users = tables[userTableIndex]?.records || [];

    tbody.innerHTML = anomalies.map(anomaly => {
      const user = users.find(u => u.ユーザーID === anomaly.ユーザーID);
      const userName = user ? user.氏名 : '不明';
      const detectionDate = new Date(anomaly.検出日時).toLocaleString('ja-JP');

      return `
        <tr data-id="${anomaly.異常値検出ログID}" style="cursor: pointer;">
          <td><input type="checkbox" class="anomaly-checkbox" data-id="${anomaly.異常値検出ログID}" style="accent-color: var(--primary);"></td>
          <td>${detectionDate}</td>
          <td>${userName}</td>
          <td>${anomaly.異常値種別}</td>
          <td>${anomaly.検出項目}</td>
          <td style="font-weight: 600;">${anomaly.検出値}</td>
          <td>${anomaly.閾値}</td>
          <td>${getSeverityBadge(anomaly.重要度)}</td>
          <td>${getStatusBadge(anomaly.確認状況)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${anomaly.異常値検出ログID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    // 統計を更新
    container.querySelector('#detection-count').textContent = anomalies.length;
    container.querySelector('#unconfirmed-count').textContent = anomalies.filter(a => a.確認状況 === '未確認').length;
  }

  // 異常値詳細を表示
  function showAnomalyDetail(anomalyId) {
    const anomaly = currentAnomalies.find(a => a.異常値検出ログID === anomalyId);
    if (!anomaly) return;

    selectedAnomalyId = anomalyId;
    const users = tables[userTableIndex]?.records || [];
    const user = users.find(u => u.ユーザーID === anomaly.ユーザーID);

    const detailContent = container.querySelector('#detail-content');
    const detailForm = container.querySelector('#detail-form');

    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
        <div>
          <div style="margin-bottom: 8px;"><strong>作業員:</strong> ${user ? user.氏名 : '不明'}</div>
          <div style="margin-bottom: 8px;"><strong>異常種別:</strong> ${anomaly.異常値種別}</div>
          <div style="margin-bottom: 8px;"><strong>検出項目:</strong> ${anomaly.検出項目}</div>
          <div style="margin-bottom: 8px;"><strong>検出値:</strong> <span style="font-weight: 600; color: #ff6a00;">${anomaly.検出値}</span></div>
        </div>
        <div>
          <div style="margin-bottom: 8px;"><strong>閾値:</strong> ${anomaly.閾値}</div>
          <div style="margin-bottom: 8px;"><strong>重要度:</strong> ${getSeverityBadge(anomaly.重要度)}</div>
          <div style="margin-bottom: 8px;"><strong>確認状況:</strong> ${getStatusBadge(anomaly.確認状況)}</div>
          <div style="margin-bottom: 8px;"><strong>検出日時:</strong> ${new Date(anomaly.検出日時).toLocaleString('ja-JP')}</div>
        </div>
      </div>
    `;

    container.querySelector('#response-memo').value = anomaly.対応メモ || '';
    detailForm.classList.remove('hidden');
  }

  // 異常値検出を実行
  async function executeDetection() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const workTimeThreshold = parseInt(container.querySelector('#work-time-threshold').value) || 12;
    const breakCountThreshold = parseInt(container.querySelector('#break-count-threshold').value) || 5;

    if (!startDate || !endDate) {
      alert('検出期間を指定してください');
      return;
    }

    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    // 進捗表示開始
    progressText.textContent = '検出処理中...';
    progressBar.style.width = '30%';

    try {
      // 作業記録を取得して異常値を検出
      const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
      if (!workRecords) {
        progressText.textContent = 'エラー: データ取得に失敗しました';
        return;
      }

      progressBar.style.width = '60%';

      const anomalies = [];
      const users = tables[userTableIndex]?.records || [];

      workRecords.forEach(record => {
        const workDate = new Date(record.作業日);
        const start = new Date(startDate);
        const end = new Date(endDate);

        if (workDate >= start && workDate <= end) {
          const user = users.find(u => u.ユーザーID === record.作業員ID);

          // 長時間作業の検出
          if (record.作業時間 && record.作業時間 > workTimeThreshold * 60) {
            anomalies.push({
              異常値検出ログID: `anomaly-${Date.now()}-${Math.random()}`,
              検出対象テーブル: '作業記録',
              検出対象レコードID: record.作業記録ID,
              ユーザーID: record.作業員ID,
              異常値種別: '長時間作業',
              検出項目: '作業時間',
              検出値: `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分`,
              閾値: `${workTimeThreshold}時間`,
              重要度: record.作業時間 > workTimeThreshold * 60 * 1.5 ? '高' : '中',
              確認状況: '未確認',
              通知送信フラグ: false,
              検出日時: new Date().toISOString(),
              作成日時: new Date().toISOString(),
              更新日時: new Date().toISOString()
            });
          }
        }
      });

      progressBar.style.width = '100%';
      progressText.textContent = `検出完了 (${anomalies.length}件)`;

      // 検出結果を保存
      for (const anomaly of anomalies) {
        await window.aivicApi.save(anomalyTableIndex, anomaly);
      }

      // 一覧を更新
      const updatedAnomalies = await window.aivicApi.list(anomalyTableIndex);
      if (updatedAnomalies) {
        currentAnomalies = updatedAnomalies;
        renderAnomalies(currentAnomalies);
      }

    } catch (error) {
      progressText.textContent = 'エラー: 検出処理に失敗しました';
      console.error('Detection error:', error);
    }
  }

  // フィルタリング
  function applyFilters() {
    const severityFilter = container.querySelector('#severity-filter').value;
    const statusFilter = container.querySelector('#status-filter').value;

    let filtered = [...currentAnomalies];

    if (severityFilter) {
      filtered = filtered.filter(a => a.重要度 === severityFilter);
    }

    if (statusFilter) {
      filtered = filtered.filter(a => a.確認状況 === statusFilter);
    }

    renderAnomalies(filtered);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    const anomalies = await window.aivicApi.list(anomalyTableIndex);
    if (anomalies) {
      currentAnomalies = anomalies;
      renderAnomalies(currentAnomalies);
    } else {
      // API未接続時は初期データを使用
      currentAnomalies = tables[anomalyTableIndex]?.records || [];
      renderAnomalies(currentAnomalies);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-detect').addEventListener('click', executeDetection);

  container.querySelector('#btn-clear-filters').addEventListener('click', () => {
    container.querySelector('#severity-filter').value = '';
    container.querySelector('#status-filter').value = '';
    renderAnomalies(currentAnomalies);
  });

  container.querySelector('#severity-filter').addEventListener('change', applyFilters);
  container.querySelector('#status-filter').addEventListener('change', applyFilters);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.anomaly-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括承認
  container.querySelector('#btn-bulk-approve').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.anomaly-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('承認する項目を選択してください');
      return;
    }

    if (!confirm(`${checkedBoxes.length}件の異常値を一括承認しますか？`)) return;

    for (const checkbox of checkedBoxes) {
      const anomalyId = checkbox.dataset.id;
      await window.aivicApi.update(anomalyTableIndex, anomalyId, {
        確認状況: '対応済み',
        確認者ID: 'current-user-id',
        確認日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      });
    }

    loadInitialData();
  });

  // 個別操作
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!selectedAnomalyId) return;

    const memo = container.querySelector('#response-memo').value;
    await window.aivicApi.update(anomalyTableIndex, selectedAnomalyId, {
      確認状況: '対応済み',
      確認者ID: 'current-user-id',
      確認日時: new Date().toISOString(),
      対応メモ: memo,
      更新日時: new Date().toISOString()
    });

    loadInitialData();
    container.querySelector('#detail-form').classList.add('hidden');
  });

  container.querySelector('#btn-reject').addEventListener('click', async () => {
    if (!selectedAnomalyId) return;

    const memo = container.querySelector('#response-memo').value;
    await window.aivicApi.update(anomalyTableIndex, selectedAnomalyId, {
      確認状況: '確認済み',
      確認者ID: 'current-user-id',
      確認日時: new Date().toISOString(),
      対応メモ: memo,
      更新日時: new Date().toISOString()
    });

    loadInitialData();
    container.querySelector('#detail-form').classList.add('hidden');
  });

  container.querySelector('#btn-view-log').addEventListener('click', () => {
    window.showScreen('scr-1778907170814'); // 異常値検出ログ画面
  });

  // 行クリックで詳細表示
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showAnomalyDetail(detailBtn.dataset.id);
      return;
    }

    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('input, button')) {
      showAnomalyDetail(row.dataset.id);
    }
  });

  // 初期化
  loadInitialData();

  // デフォルト日付設定
  const today = new Date();
  const oneWeekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#start-date').value = oneWeekAgo.toISOString().split('T')[0];
  container.querySelector('#end-date').value = today.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let currentRecordId = null;
  let originalData = null;

  // 作業記録データの再描画
  function loadWorkRecords() {
    window.aivicApi.list(1).then(records => {
      const selectRecord = container.querySelector("#select-record");
      selectRecord.innerHTML = '<option value="">記録を選択してください</option>';

      if (records) {
        records.forEach(record => {
          const option = document.createElement("option");
          option.value = record.id;
          option.textContent = `${record.作業日} - ${record.プロジェクト名} (${record.作業種別})`;
          selectRecord.appendChild(option);
        });
      }
    });
  }

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    window.aivicApi.list(3).then(items => {
      const selectWorkItem = container.querySelector("#select-work-item");
      selectWorkItem.innerHTML = '<option value="">選択してください</option>';

      if (items) {
        items.filter(item => item.有効フラグ).forEach(item => {
          const option = document.createElement("option");
          option.value = item.id;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          selectWorkItem.appendChild(option);
        });
      }
    });
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = container.querySelector("#input-break-time").value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      let totalMinutes = (end - start) / (1000 * 60);

      let breakMinutes = 0;
      if (breakTime) {
        const breakStart = new Date(`2000-01-01T${breakTime}`);
        breakMinutes = 30; // デフォルト30分の中断
        container.querySelector("#display-break-duration").textContent = `${breakMinutes}分`;
      } else {
        container.querySelector("#display-break-duration").textContent = "なし";
      }

      const actualMinutes = totalMinutes - breakMinutes;
      const hours = Math.floor(actualMinutes / 60);
      const minutes = actualMinutes % 60;

      container.querySelector("#display-actual-work-time").textContent = `${hours}時間${minutes}分`;

      // 異常値チェック
      checkAnomalies(actualMinutes);
    }
  }

  // 異常値チェック
  function checkAnomalies(actualMinutes) {
    const warningArea = container.querySelector("#warning-area");
    const warningMessage = container.querySelector("#warning-message");

    let warnings = [];

    if (actualMinutes > 600) { // 10時間超過
      warnings.push("作業時間が10時間を超えています");
    }
    if (actualMinutes < 30) { // 30分未満
      warnings.push("作業時間が30分未満です");
    }

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join(", ");
      warningArea.style.display = "block";
    } else {
      warningArea.style.display = "none";
    }
  }

  // 修正前データ表示
  function displayOriginalData(record) {
    const area = container.querySelector("#original-data-area");
    if (!record) {
      area.innerHTML = "記録を選択してください";
      return;
    }

    const startDate = new Date(record.作業開始時刻);
    const endDate = record.作業終了時刻? new Date(record.作業終了時刻) : null;

    area.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${record.作業日}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startDate.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'})}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endDate ? endDate.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '未設定'}</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト:</strong> ${record.プロジェクト名}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${record.作業種別}</div>
      <div style="margin-bottom: 8px;"><strong>作業時間:</strong> ${record.作業時間 ? Math.floor(record.作業時間/60) + '時間' + (record.作業時間%60) + '分' : '未計算'}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${record.進捗状況}</div>
    `;
  }

  // 初期データ読み込み
  loadWorkRecords();
  loadWorkItems();

  // 記録選択時の処理
  container.querySelector("#select-record").addEventListener("change", async (e) => {
    const recordId = e.target.value;
    if (!recordId) {
      currentRecordId = null;
      originalData = null;
      displayOriginalData(null);
      return;
    }

    const records = await window.aivicApi.list(1);
    const record = records?.find(r => r.id === recordId);
    if (record) {
      currentRecordId = recordId;
      originalData = record;
      displayOriginalData(record);

      // フォームに現在の値を設定
      const startDate = new Date(record.作業開始時刻);
      const endDate = record.作業終了時刻? new Date(record.作業終了時刻) : null;

      container.querySelector("#input-work-date").value = record.作業日;
      container.querySelector("#input-start-time").value = startDate.toTimeString().slice(0, 5);
      if (endDate) {
        container.querySelector("#input-end-time").value = endDate.toTimeString().slice(0, 5);
      }

      calculateTimes();
    }
  });

  // 時間入力時の自動計算
  ["#input-start-time", "#input-end-time", "#input-break-time"].forEach(selector => {
    container.querySelector(selector).addEventListener("change", calculateTimes);
  });

  // 保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async () => {
    if (!currentRecordId) {
      alert("修正対象の記録を選択してください");
      return;
    }

    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    if (!correctionReason) {
      alert("修正理由を入力してください");
      return;
    }

    const workDate = container.querySelector("#input-work-date").value;
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;

    if (!workDate || !startTime || !endTime) {
      alert("必須項目を入力してください");
      return;
    }

    const startDateTime = new Date(`${workDate}T${startTime}`);
    const endDateTime = new Date(`${workDate}T${endTime}`);
    const workMinutes = (endDateTime - startDateTime) / (1000 * 60);

    const updateData = {
      作業日: workDate,
      作業開始時刻: startDateTime.toISOString(),
      作業終了時刻: endDateTime.toISOString(),
      作業時間: workMinutes,
      更新日時: new Date().toISOString()
    };

    const result = await window.aivicApi.update(1, currentRecordId, updateData);
    if (result) {
      alert("修正が保存されました");
      window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907145716"); // 作業履歴一覧画面
  });
}

function(container, apiUrl, tables) {
  let selectedPriority = '';
  let uploadedFiles = [];

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector('#report-tbody');
    tbody.innerHTML = rows.map(r => {
      const priorityBadge = r.緊急度 === '高' ? 
        `<span style="background: #ff4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${r.緊急度||''}</span>` :
        r.緊急度 === '中' ? 
        `<span style="background: #ff8800; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${r.緊急度||''}</span>` :
        `<span style="background: #666; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${r.緊急度||''}</span>`;

      const statusBadge = r.対応状況 === '対応済み' ?
        `<span style="background: #22c55e; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${r.対応状況||'未対応'}</span>` :
        `<span style="background: #f59e0b; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${r.対応状況||'未対応'}</span>`;

      return `<tr data-id="${r.id}">
        <td>${priorityBadge}</td>
        <td>${r.報告種別||''}</td>
        <td>${r.発生日時 ? new Date(r.発生日時).toLocaleString() : ''}</td>
        <td>${r.発生場所||''}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.緊急事態内容||''}</td>
        <td>${r.報告者名||''}</td>
        <td>${statusBadge}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
        </td>
      </tr>`;
    }).join('');
  }

  // 2. 初期データを即座に描画
  renderRows(tables[5]?.records || []);

  // 作業項目マスタの読み込み
  if (tables[3]?.records) {
    const workItemSelect = container.querySelector('#work-item');
    tables[3].records.forEach(item => {
      if (item.有効フラグ) {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = item.作業項目名;
        workItemSelect.appendChild(option);
      }
    });
  }

  // 現在のユーザー名を設定（仮）
  container.querySelector('#reporter-name').value = 'ログイン中ユーザー';

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#occurred-at').value = now.toISOString().slice(0, 16);

  // 緊急度ボタンの処理
  container.querySelectorAll('.priority-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      container.querySelectorAll('.priority-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = 'var(--text)';
      });
      btn.style.background = 'var(--primary)';
      btn.style.color = '#fff';
      selectedPriority = btn.dataset.priority;
    });
  });

  // 写真アップロードの処理
  container.querySelector('#photo-upload').addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    uploadedFiles = files;

    if (files.length > 0) {
      const previewDiv = container.querySelector('#image-preview');
      const previewContainer = container.querySelector('#preview-container');

      previewContainer.innerHTML = '';
      files.forEach((file, index) => {
        const reader = new FileReader();
        reader.onload = (e) => {
          const img = document.createElement('img');
          img.src = e.target.result;
          img.style.cssText = 'width: 80px; height: 80px; object-fit: cover; border-radius: 6px; border: 1px solid rgba(255,255,255,0.18);';
          previewContainer.appendChild(img);
        };
        reader.readAsDataURL(file);
      });

      previewDiv.style.display = 'block';
    } else {
      container.querySelector('#image-preview').style.display = 'none';
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-input').value;
    const rows = await window.aivicApi.list(5);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderRows(filtered);
    }
  });

  // 4. 即座に報告ボタンのイベントリスナー
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    if (!selectedPriority) {
      alert('緊急度を選択してください');
      return;
    }

    const reportType = container.querySelector('#report-type').value;
    if (!reportType) {
      alert('報告種別を選択してください');
      return;
    }

    const description = container.querySelector('#description').value;
    if (!description.trim()) {
      alert('緊急事態内容を入力してください');
      return;
    }

    const reportData = {
      緊急度: selectedPriority,
      報告種別: reportType,
      発生日時: container.querySelector('#occurred-at').value,
      発生場所: container.querySelector('#location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: description,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      対応状況: '未対応',
      添付ファイル数: uploadedFiles.length,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(5, reportData);
    if (saved) {
      alert('緊急報告を送信しました');
      // フォームをクリア
      container.querySelectorAll('.priority-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = 'var(--text)';
      });
      selectedPriority = '';
      container.querySelector('#report-type').value = '';
      container.querySelector('#location').value = '';
      container.querySelector('#work-item').value = '';
      container.querySelector('#description').value = '';
      container.querySelector('#contact-phone').value = '';
      container.querySelector('#photo-upload').value = '';
      container.querySelector('#image-preview').style.display = 'none';
      uploadedFiles = [];

      // 一覧を更新
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);

      // 工数記録画面に遷移
      window.showScreen("scr-1778907133295");
    }
  });

  // 5. 下書き保存ボタンのイベントリスナー
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const reportData = {
      緊急度: selectedPriority,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurred-at').value,
      発生場所: container.querySelector('#location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#description').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      対応状況: '下書き',
      添付ファイル数: uploadedFiles.length,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(5, reportData);
    if (saved) {
      alert('下書きを保存しました');
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);
    }
  });

  // 6. 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この緊急報告を削除しますか？')) return;
      await window.aivicApi.delete(5, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(5);
      if (rows) renderRows(rows);
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const rows = await window.aivicApi.list(5);
      if (rows) {
        const record = rows.find(r => r.id === editBtn.dataset.id);
        if (record) {
          // フォームに既存データを設定
          if (record.緊急度) {
            container.querySelectorAll('.priority-btn').forEach(b => {
              if (b.dataset.priority === record.緊急度) {
                b.style.background = 'var(--primary)';
                b.style.color = '#fff';
                selectedPriority = record.緊急度;
              } else {
                b.style.background = 'transparent';
                b.style.color = 'var(--text)';
              }
            });
          }
          container.querySelector('#report-type').value = record.報告種別 || '';
          container.querySelector('#occurred-at').value = record.発生日時 || '';
          container.querySelector('#location').value = record.発生場所 || '';
          container.querySelector('#work-item').value = record.作業項目ID || '';
          container.querySelector('#description').value = record.緊急事態内容 || '';
          container.querySelector('#contact-phone').value = record.連絡先電話番号 || '';
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let workRecords = [];
  let workItems = [];

  // 作業記録とマスタデータの読み込み
  async function loadData() {
    workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
    workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

    // 作業記録ドロップダウンの設定
    const selectWorkRecord = container.querySelector("#select-work-record");
    selectWorkRecord.innerHTML = '<option value="">選択してください</option>' +
      workRecords.map(r => `<option value="${r.id}">${r.作業日 ? new Date(r.作業日).toLocaleDateString() : ''} - ${r.プロジェクト名 || ''} (${r.作業種別 || ''})</option>`).join("");

    // 作業項目ドロップダウンの設定
    const selectWorkItem = container.querySelector("#select-work-item");
    selectWorkItem.innerHTML = '<option value="">選択してください</option>' +
      workItems.filter(item => item.有効フラグ).map(item => `<option value="${item.id}">${item.作業項目名}</option>`).join("");
  }

  // 時間計算
  function calculateTime() {
    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const breakTime = parseInt(container.querySelector("#input-break-time").value) || 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01 ${startTime}`);
      const end = new Date(`2000-01-01 ${endTime}`);
      const diffMinutes = (end - start) / (1000 * 60);

      if (diffMinutes > 0) {
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        container.querySelector("#input-actual-time").value = `${hours}時間${minutes}分`;

        const netMinutes = diffMinutes - breakTime;
        if (netMinutes >= 0) {
          const netHours = Math.floor(netMinutes / 60);
          const netMins = netMinutes % 60;
          container.querySelector("#input-net-time").value = `${netHours}時間${netMins}分`;

          // 異常値チェック
          checkAbnormalValues(diffMinutes, breakTime);
        }
      }
    }
  }

  // 異常値チェック
  function checkAbnormalValues(totalMinutes, breakMinutes) {
    const warningArea = container.querySelector("#warning-area");
    const warningMessage = container.querySelector("#warning-message");
    let warnings = [];

    if (totalMinutes > 12 * 60) {
      warnings.push("作業時間が12時間を超えています");
    }
    if (breakMinutes > totalMinutes * 0.5) {
      warnings.push("中断時間が作業時間の50%を超えています");
    }
    if (totalMinutes < 30) {
      warnings.push("作業時間が30分未満です");
    }

    if (warnings.length > 0) {
      warningMessage.textContent = warnings.join("、");
      warningArea.classList.remove("hidden");
    } else {
      warningArea.classList.add("hidden");
    }
  }

  // 作業記録選択時の処理
  container.querySelector("#select-work-record").addEventListener("change", function() {
    const recordId = this.value;
    currentWorkRecord = workRecords.find(r => r.id === recordId);

    if (currentWorkRecord) {
      // フォームに元データを設定
      const workDate = currentWorkRecord.作業日 ? new Date(currentWorkRecord.作業日).toLocaleDateString() : '';
      container.querySelector("#input-work-date").value = workDate;

      if (currentWorkRecord.作業開始時刻) {
        const startTime = new Date(currentWorkRecord.作業開始時刻);
        container.querySelector("#input-start-time").value = startTime.toTimeString().slice(0, 5);
      }

      if (currentWorkRecord.作業終了時刻) {
        const endTime = new Date(currentWorkRecord.作業終了時刻);
        container.querySelector("#input-end-time").value = endTime.toTimeString().slice(0, 5);
      }

      container.querySelector("#textarea-work-detail").value = currentWorkRecord.作業内容 || '';

      // 元データ表示を更新
      container.querySelector("#orig-date").textContent = workDate;
      container.querySelector("#orig-time").textContent = 
        `${currentWorkRecord.作業開始時刻 ? new Date(currentWorkRecord.作業開始時刻).toTimeString().slice(0, 5) : '-'} ～ ${currentWorkRecord.作業終了時刻 ? new Date(currentWorkRecord.作業終了時刻).toTimeString().slice(0, 5) : '-'}`;
      container.querySelector("#orig-duration").textContent = currentWorkRecord.作業時間 ? `${Math.floor(currentWorkRecord.作業時間 / 60)}時間${currentWorkRecord.作業時間 % 60}分` : '-';
      container.querySelector("#orig-project").textContent = currentWorkRecord.プロジェクト名 || '-';
      container.querySelector("#orig-location").textContent = currentWorkRecord.作業場所 || '-';
      container.querySelector("#orig-type").textContent = currentWorkRecord.作業種別 || '-';
      container.querySelector("#orig-content").textContent = currentWorkRecord.作業内容 || '-';

      calculateTime();
    }
  });

  // 時間入力時の自動計算
  container.querySelector("#input-start-time").addEventListener("change", calculateTime);
  container.querySelector("#input-end-time").addEventListener("change", calculateTime);
  container.querySelector("#input-break-time").addEventListener("input", calculateTime);

  // 元データ参照ボタン
  container.querySelector("#btn-show-original").addEventListener("click", function() {
    if (!currentWorkRecord) {
      alert("修正対象の作業記録を選択してください");
      return;
    }
    // 元データ表示パネルをハイライト
    const originalPanel = container.querySelector(".card:last-child");
    originalPanel.style.border = "2px solid var(--primary)";
    setTimeout(() => {
      originalPanel.style.border = "";
    }, 2000);
  });

  // 修正完了ボタン
  container.querySelector("#btn-update").addEventListener("click", async function() {
    if (!currentWorkRecord) {
      alert("修正対象の作業記録を選択してください");
      return;
    }

    const correctionReason = container.querySelector("#input-correction-reason").value.trim();
    if (!correctionReason) {
      alert("修正理由を入力してください");
      return;
    }

    const startTime = container.querySelector("#input-start-time").value;
    const endTime = container.querySelector("#input-end-time").value;
    const workDetail = container.querySelector("#textarea-work-detail").value.trim();
    const workItemId = container.querySelector("#select-work-item").value;

    if (!startTime || !endTime || !workDetail) {
      alert("必須項目を入力してください");
      return;
    }

    // 作業時間を計算
    const start = new Date(`2000-01-01 ${startTime}`);
    const end = new Date(`2000-01-01 ${endTime}`);
    const workMinutes = (end - start) / (1000 * 60);
    const breakMinutes = parseInt(container.querySelector("#input-break-time").value) || 0;

    // 作業記録を更新
    const updateData = {
      作業開始時刻: new Date(`${currentWorkRecord.作業日.split('T')[0]} ${startTime}`).toISOString(),
      作業終了時刻: new Date(`${currentWorkRecord.作業日.split('T')[0]} ${endTime}`).toISOString(),
      作業時間: Math.max(0, workMinutes - breakMinutes),
      作業内容: workDetail,
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentWorkRecord.id, updateData);
    if (updated) {
      // 修正ログを記録（異常値検出ログテーブルを利用）
      const logData = {
        検出対象テーブル: '作業記録',
        検出対象レコードID: currentWorkRecord.id,
        ユーザーID: currentWorkRecord.作業員ID,
        異常値種別: '手動修正',
        検出項目: '作業時間・作業内容',
        検出値: correctionReason,
        閾値: '手動修正',
        重要度: '中',
        確認状況: '対応済み',
        通知送信フラグ: false,
        対応メモ: `修正理由: ${correctionReason}`,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      await window.aivicApi.save(4, logData);

      alert("工数修正が完了しました");
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let users = [];
  let workItems = [];
  let filteredRecords = [];

  // 初期データ設定
  function initializeData() {
    workRecords = tables[1]?.records || [];
    users = tables[0]?.records || [];
    workItems = tables[3]?.records || [];

    // 作業員選択肢を設定
    const workerSelect = container.querySelector("#select-workers");
    workerSelect.innerHTML = users.map(user => 
      `<option value="${user.id}">${user.氏名 || user.ユーザー名}</option>`
    ).join("");

    // 作業項目選択肢を設定
    const workItemSelect = container.querySelector("#select-work-items");
    workItemSelect.innerHTML = workItems.filter(item => item.有効フラグ).map(item => 
      `<option value="${item.id}">${item.作業項目名}</option>`
    ).join("");
  }

  // プレビューテーブル再描画
  function renderPreviewTable(records) {
    const tbody = container.querySelector("#preview-table-body");
    if (!records || records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">該当するデータがありません</td></tr>';
      return;
    }

    tbody.innerHTML = records.slice(0, 10).map(record => {
      const user = users.find(u => u.id === record.作業員ID);
      const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString() : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}h${record.作業時間 % 60}m` : '';

      return `
        <tr>
          <td>${workDate}</td>
          <td>${user?.氏名 || user?.ユーザー名 || ''}</td>
          <td>${record.プロジェクト名 || ''}</td>
          <td>${record.作業場所 || ''}</td>
          <td>${record.作業種別 || ''}</td>
          <td>${workTime}</td>
          <td>${record.進捗状況 || ''}</td>
        </tr>
      `;
    }).join("");

    if (records.length > 10) {
      tbody.innerHTML += `<tr><td colspan="7" style="text-align: center; color: var(--text-muted); font-style: italic;">他${records.length - 10}件...</td></tr>`;
    }
  }

  // 条件プレビュー更新
  function updateConditionPreview() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const selectedWorkers = Array.from(container.querySelector("#select-workers").selectedOptions).map(o => o.text);
    const selectedWorkItems = Array.from(container.querySelector("#select-work-items").selectedOptions).map(o => o.text);
    const location = container.querySelector("#input-location").value;
    const anomalyOption = container.querySelector("#select-anomaly").value;
    const interruptionOption = container.querySelector("#select-interruption").value;
    const format = container.querySelector("#select-format").value;

    let conditions = [];
    if (startDate) conditions.push(`開始日: ${startDate}`);
    if (endDate) conditions.push(`終了日: ${endDate}`);
    if (selectedWorkers.length > 0) conditions.push(`作業員: ${selectedWorkers.join(', ')}`);
    if (selectedWorkItems.length > 0) conditions.push(`作業項目: ${selectedWorkItems.join(', ')}`);
    if (location) conditions.push(`作業場所: ${location}`);
    conditions.push(`異常値データ: ${anomalyOption === 'include' ? '含む' : '除外'}`);
    conditions.push(`中断記録: ${interruptionOption === 'include' ? '含む' : '除外'}`);
    conditions.push(`出力形式: ${format.toUpperCase()}`);

    const previewContent = container.querySelector("#preview-content");
    previewContent.innerHTML = conditions.length > 0 ? conditions.join(' | ') : '条件が設定されていません';
  }

  // データフィルタリング
  function filterData() {
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const selectedWorkerIds = Array.from(container.querySelector("#select-workers").selectedOptions).map(o => o.value);
    const selectedWorkItemIds = Array.from(container.querySelector("#select-work-items").selectedOptions).map(o => o.value);
    const location = container.querySelector("#input-location").value.toLowerCase();

    filteredRecords = workRecords.filter(record => {
      // 日付範囲フィルター
      if (startDate && record.作業日 && new Date(record.作業日) < new Date(startDate)) return false;
      if (endDate && record.作業日 && new Date(record.作業日) > new Date(endDate)) return false;

      // 作業員フィルター
      if (selectedWorkerIds.length > 0 && !selectedWorkerIds.includes(record.作業員ID)) return false;

      // 作業場所フィルター
      if (location && (!record.作業場所 || !record.作業場所.toLowerCase().includes(location))) return false;

      return true;
    });

    container.querySelector("#data-count").textContent = filteredRecords.length;
    renderPreviewTable(filteredRecords);
  }

  // CSVエクスポート
  function exportToCSV(records) {
    const headers = ['作業日', '作業員', 'プロジェクト名', '作業場所', '作業種別', '作業内容', '作業時間(分)', '進捗状況', '承認状態'];
    const csvContent = [
      headers.join(','),
      ...records.map(record => {
        const user = users.find(u => u.id === record.作業員ID);
        return [
          record.作業日 ? new Date(record.作業日).toLocaleDateString() : '',
          user?.氏名 || user?.ユーザー名 || '',
          record.プロジェクト名 || '',
          record.作業場所 || '',
          record.作業種別 || '',
          `"${(record.作業内容 || '').replace(/"/g, '""')}"`,
          record.作業時間 || '',
          record.進捗状況 || '',
          record.承認状態 || ''
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `工数記録データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initializeData();

  // イベントリスナー
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907145716");
  });

  container.querySelector("#btn-preview").addEventListener("click", () => {
    updateConditionPreview();
    filterData();
  });

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-start-date").value = '';
    container.querySelector("#input-end-date").value = '';
    container.querySelector("#input-location").value = '';
    container.querySelector("#select-workers").selectedIndex = -1;
    container.querySelector("#select-work-items").selectedIndex = -1;
    container.querySelector("#select-anomaly").value = 'include';
    container.querySelector("#select-interruption").value = 'include';
    container.querySelector("#select-format").value = 'csv';
    container.querySelector("#preview-content").innerHTML = '条件を設定してプレビューボタンをクリックしてください';
    container.querySelector("#data-count").textContent = '0';
    renderPreviewTable([]);
  });

  container.querySelector("#btn-save-condition").addEventListener("click", () => {
    const conditions = {
      startDate: container.querySelector("#input-start-date").value,
      endDate: container.querySelector("#input-end-date").value,
      selectedWorkers: Array.from(container.querySelector("#select-workers").selectedOptions).map(o => o.value),
      selectedWorkItems: Array.from(container.querySelector("#select-work-items").selectedOptions).map(o => o.value),
      location: container.querySelector("#input-location").value,
      anomaly: container.querySelector("#select-anomaly").value,
      interruption: container.querySelector("#select-interruption").value,
      format: container.querySelector("#select-format").value
    };

    localStorage.setItem('workDataExtractionConditions', JSON.stringify(conditions));
    alert('抽出条件を保存しました');
  });

  container.querySelector("#btn-extract").addEventListener("click", () => {
    if (filteredRecords.length === 0) {
      alert('抽出するデータがありません。条件を確認してください。');
      return;
    }

    const format = container.querySelector("#select-format").value;
    if (format === 'csv') {
      exportToCSV(filteredRecords);
    } else {
      alert('Excel形式のエクスポートは現在準備中です。CSVをご利用ください。');
    }
  });

  // 保存された条件の復元
  const savedConditions = localStorage.getItem('workDataExtractionConditions');
  if (savedConditions) {
    try {
      const conditions = JSON.parse(savedConditions);
      container.querySelector("#input-start-date").value = conditions.startDate || '';
      container.querySelector("#input-end-date").value = conditions.endDate || '';
      container.querySelector("#input-location").value = conditions.location || '';
      container.querySelector("#select-anomaly").value = conditions.anomaly || 'include';
      container.querySelector("#select-interruption").value = conditions.interruption || 'include';
      container.querySelector("#select-format").value = conditions.format || 'csv';

      if (conditions.selectedWorkers) {
        Array.from(container.querySelector("#select-workers").options).forEach(option => {
          option.selected = conditions.selectedWorkers.includes(option.value);
        });
      }

      if (conditions.selectedWorkItems) {
        Array.from(container.querySelector("#select-work-items").options).forEach(option => {
          option.selected = conditions.selectedWorkItems.includes(option.value);
        });
      }
    } catch (e) {
      console.error('保存された条件の復元に失敗しました:', e);
    }
  }
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;

  // 中断記録テーブル再描画
  function renderBreakRecords(breakRecords) {
    const tbody = container.querySelector("#break-records-tbody");
    if (!breakRecords || breakRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">中断記録がありません</td></tr>';
      return;
    }

    tbody.innerHTML = breakRecords.map(record => {
      const startTime = record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-';
      const endTime = record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '作業中';
      const duration = record.中断時間 ? `${record.中断時間}分` : '-';
      const impactColor = record.影響度 === '重大' ? '#ef4444' : record.影響度 === '中程度' ? '#f59e0b' : '#6b7280';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${duration}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.中断理由区分 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.中断理由詳細 || '-'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: ${impactColor};">${record.影響度 || '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // 作業記録詳細表示
  function displayWorkRecord(record) {
    if (!record) return;

    currentWorkRecord = record;

    // 基本情報
    const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString('ja-JP') : '-';
    container.querySelector("#work-date").textContent = workDate;

    // 作業者名を取得（ユーザーテーブルから）
    const userTable = tables[0]; // ユーザーテーブル
    const user = userTable.records.find(u => u.ユーザーID === record.作業員ID);
    container.querySelector("#worker-name").textContent = user ? user.氏名 : '-';

    // 承認状態
    const statusBadge = container.querySelector("#approval-status");
    const status = record.承認状態 || '未承認';
    statusBadge.textContent = status;
    statusBadge.style.background = status === '承認済み' ? '#22c55e' : status === '差し戻し' ? '#ef4444' : '#6b7280';
    statusBadge.style.color = '#fff';

    // 時間情報
    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleString('ja-JP') : '-';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleString('ja-JP') : '作業中';
    const workDuration = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '-';

    container.querySelector("#start-time").textContent = startTime;
    container.querySelector("#end-time").textContent = endTime;
    container.querySelector("#work-duration").textContent = workDuration;

    // 作業詳細
    container.querySelector("#project-name").textContent = record.プロジェクト名 || '-';
    container.querySelector("#work-location").textContent = record.作業場所 || '-';
    container.querySelector("#work-type").textContent = record.作業種別 || '-';
    container.querySelector("#progress-status").textContent = record.進捗状況 || '-';
    container.querySelector("#work-content").textContent = record.作業内容 || '-';
    container.querySelector("#remarks").textContent = record.備考 || '-';

    // 中断時間の計算と表示
    calculateBreakTime(record.作業記録ID);

    // 異常値警告の確認
    checkAnomalyWarning(record.作業記録ID);
  }

  // 中断時間計算
  async function calculateBreakTime(workRecordId) {
    try {
      const breakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (!breakRecords) return;

      const relatedBreaks = breakRecords.filter(br => br.作業記録ID === workRecordId);
      const totalBreakTime = relatedBreaks.reduce((sum, br) => sum + (br.中断時間 || 0), 0);

      const breakDuration = totalBreakTime > 0 ? `${Math.floor(totalBreakTime / 60)}時間${totalBreakTime % 60}分` : '0分';
      container.querySelector("#break-duration").textContent = breakDuration;

      // 中断記録テーブル表示
      renderBreakRecords(relatedBreaks);
    } catch (error) {
      console.error('中断記録の取得に失敗:', error);
      container.querySelector("#break-duration").textContent = '-';
    }
  }

  // 異常値警告確認
  async function checkAnomalyWarning(workRecordId) {
    try {
      const anomalyLogs = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (!anomalyLogs) return;

      const hasAnomaly = anomalyLogs.some(log => 
        log.検出対象レコードID === workRecordId && log.確認状況 === '未確認'
      );

      const warningElement = container.querySelector("#anomaly-warning");
      if (hasAnomaly) {
        warningElement.classList.remove('hidden');
      } else {
        warningElement.classList.add('hidden');
      }
    } catch (error) {
      console.error('異常値ログの確認に失敗:', error);
    }
  }

  // 初期データ表示（最初の作業記録を表示）
  const workRecords = tables[1].records || []; // 作業記録テーブル
  if (workRecords.length > 0) {
    displayWorkRecord(workRecords[0]);
  }

  // 修正ボタン
  container.querySelector("#btn-modify").addEventListener("click", () => {
    if (currentWorkRecord) {
      // 修正画面に遷移（作業記録IDをパラメータとして渡す想定）
      window.showScreen("scr-1778907343735");
    }
  });

  // 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!currentWorkRecord) return;

    if (!confirm('この工数記録を承認しますか？')) return;

    try {
      const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, {
        承認状態: '承認済み',
        承認日時: new Date().toISOString(),
        承認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      });

      if (updated) {
        // 承認状態を更新
        currentWorkRecord.承認状態 = '承認済み';
        displayWorkRecord(currentWorkRecord);

        // 関連する異常値ログを確認済みに更新
        const anomalyLogs = await window.aivicApi.list(4);
        if (anomalyLogs) {
          const relatedLogs = anomalyLogs.filter(log => 
            log.検出対象レコードID === currentWorkRecord.作業記録ID && log.確認状況 === '未確認'
          );

          for (const log of relatedLogs) {
            await window.aivicApi.update(4, log.異常値検出ログID, {
              確認状況: '確認済み',
              確認者ID: 'current-user-id',
              確認日時: new Date().toISOString(),
              対応メモ: '承認時に確認済み'
            });
          }
        }

        alert('工数記録を承認しました。');
      }
    } catch (error) {
      console.error('承認処理に失敗:', error);
      alert('承認処理に失敗しました。');
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#input-work-date').value = today;

  // 作業項目マスタを読み込んでセレクトボックスに設定
  function loadWorkItems() {
    window.aivicApi.list(3).then(workItems => {
      if (workItems) {
        const select = container.querySelector('#select-work-item');
        select.innerHTML = '<option value="">選択してください</option>';
        workItems.filter(item => item.有効フラグ).forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          select.appendChild(option);
        });
      }
    });
  }

  // 中断記録の再描画
  function renderBreakRecords(records) {
    const tbody = container.querySelector('#break-records-tbody');
    tbody.innerHTML = records.map(record => `
      <tr data-id="${record.中断記録ID}">
        <td>${record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : ''}</td>
        <td>${record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '作業中'}</td>
        <td>${record.中断時間 ? Math.floor(record.中断時間 / 60) + '時間' + (record.中断時間 % 60) + '分' : '-'}</td>
        <td>${record.中断理由区分 || ''}</td>
        <td>${record.中断理由詳細 || ''}</td>
        <td>
          <button class="action-btn secondary delete-break-btn" data-id="${record.中断記録ID}" style="font-size: 11px; padding: 2px 6px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 工数計算
  function calculateWorkHours() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}`);
      const end = new Date(`2000-01-01T${endTime}`);
      const diffMs = end - start;
      const diffMinutes = Math.floor(diffMs / (1000 * 60));

      if (diffMinutes > 0) {
        const hours = Math.floor(diffMinutes / 60);
        const minutes = diffMinutes % 60;
        container.querySelector('#display-work-hours').textContent = `${hours}時間 ${minutes}分`;

        // 中断時間を計算（仮で0時間とする）
        const breakMinutes = 0; // 実際は中断記録から計算
        const actualMinutes = diffMinutes - breakMinutes;
        const actualHours = Math.floor(actualMinutes / 60);
        const actualMins = actualMinutes % 60;
        container.querySelector('#display-actual-hours').textContent = `${actualHours}時間 ${actualMins}分`;
      }
    }
  }

  // 初期データ読み込み
  loadWorkItems();
  renderBreakRecords(tables[2]?.records || []);

  // 時刻変更時の工数計算
  container.querySelector('#input-start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#input-end-time').addEventListener('change', calculateWorkHours);

  // 履歴一覧ボタン
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716');
  });

  // 中断記録ボタン
  container.querySelector('#btn-break-record').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 中断追加ボタン
  container.querySelector('#btn-add-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    const workDate = container.querySelector('#input-work-date').value;
    const workItemId = container.querySelector('#select-work-item').value;
    const workLocation = container.querySelector('#input-work-location').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const projectName = container.querySelector('#input-project-name').value;
    const workType = container.querySelector('input[name="work-type"]:checked')?.value;
    const workContent = container.querySelector('#textarea-work-content').value;
    const remarks = container.querySelector('#textarea-remarks').value;

    if (!workDate || !workItemId || !workLocation || !startTime || !projectName || !workType || !workContent) {
      alert('必須項目を入力してください');
      return;
    }

    const workRecord = {
      作業員ID: 'current-user-id', // 実際はログインユーザーIDを使用
      作業日: workDate,
      作業開始時刻: `${workDate}T${startTime}`,
      作業終了時刻: endTime ? `${workDate}T${endTime}` : null,
      プロジェクト名: projectName,
      作業場所: workLocation,
      作業種別: workType,
      作業内容: workContent,
      進捗状況: '作業中',
      備考: remarks,
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      alert('一時保存しました');
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const workDate = container.querySelector('#input-work-date').value;
    const workItemId = container.querySelector('#select-work-item').value;
    const workLocation = container.querySelector('#input-work-location').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const projectName = container.querySelector('#input-project-name').value;
    const workType = container.querySelector('input[name="work-type"]:checked')?.value;
    const workContent = container.querySelector('#textarea-work-content').value;
    const remarks = container.querySelector('#textarea-remarks').value;

    if (!workDate || !workItemId || !workLocation || !startTime || !endTime || !projectName || !workType || !workContent) {
      alert('必須項目を入力してください（終了時刻も必須です）');
      return;
    }

    // 作業時間計算
    const start = new Date(`${workDate}T${startTime}`);
    const end = new Date(`${workDate}T${endTime}`);
    const workMinutes = Math.floor((end - start) / (1000 * 60));

    const workRecord = {
      作業員ID: 'current-user-id',
      作業日: workDate,
      作業開始時刻: `${workDate}T${startTime}`,
      作業終了時刻: `${workDate}T${endTime}`,
      作業時間: workMinutes,
      プロジェクト名: projectName,
      作業場所: workLocation,
      作業種別: workType,
      作業内容: workContent,
      進捗状況: '完了',
      備考: remarks,
      承認状態: '未承認',
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      alert('工数記録を確定しました');
      window.showScreen('scr-1778907226171'); // 記録確認画面へ
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容を破棄してよろしいですか？')) {
      window.showScreen('scr-1778907133295'); // 工数記録画面へ
    }
  });

  // 中断記録削除のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-break-btn');
    if (deleteBtn) {
      if (!confirm('この中断記録を削除しますか？')) return;

      const breakId = deleteBtn.dataset.id;
      await window.aivicApi.delete(2, breakId);

      // 中断記録を再読み込み
      const breakRecords = await window.aivicApi.list(2);
      if (breakRecords) {
        renderBreakRecords(breakRecords);
      }
    }
  });
}
